  str_monster_name_2902701_en = "Forsakin",
  str_monster_name_2000271_en = "Lumo Ranger",
  str_monster_desc_2900063 = "Dizem que é um dos membros da organização misteriosa, o Eclipse. Além de ter ataques poderosos, também pode comandar os Eclipsitas.",
  str_monster_desc_2900141 = "Membro da organização misteriosa Eclipse, ela e sua irmã Shire compõem as Gêmeas Víbora. Ela fará de tudo para alcançar seu objetivo.",
  str_monster_desc_2900181 = "Membro da misteriosa organização Eclipse, ela e sua irmã Shelt compõem as Gêmeas Víbora. Impulsiva, ela mata inimigos com brutalidade e crueldade.",
  str_monster_desc_2900201 = "Dizem que é um dos membros da organização misteriosa, o Eclipse. Além de ter ataques poderosos, também pode comandar os Eclipsitas.",
  str_monster_desc_2900211 = "Violento e gigante, é um Eclipsita poderoso que parece aguentar sofrimento infinito. Melhor ficar longe dele.",
  str_monster_desc_2900221 = "Uma fusão de Shelt e Shire. Por sofrer uma dor terrível, tem um forte desejo por vingança, que o torna um Eclipsita poderoso e violento.",
  str_monster_desc_2900231 = "A criatura que protege a Colossus Mantiz, que possui uma tecnologia anciã misteriosa. Cuidado com isso.",
  str_monster_desc_2900232 = "A criatura que protege a Colossus Mantiz, que possui uma tecnologia anciã misteriosa. Cuidado com isso.",
  str_monster_desc_2900241 = "Sua força destrutiva é o bastante para destruir todo um exército. Dizem que é um subordinado leal de um membro da organização Eclipsita.",
  str_monster_desc_2900251 = "Extremamente ágil, pode parecer um fantasma que vai e vem sem deixar nenhum rastro, e meios comuns não conseguem feri-lo. Também conhecido como Caçador de Almas.",
  str_monster_desc_2000011 = "A unidade de combate principal dos Eclipsitas, com habilidades de luta superiores às dos Opressores. São conhecidos como Capitães e geralmente são vistos comandando os Opressores.",
  str_monster_desc_2000071 = "Um Eclipsita gigante responsável pela destruição de várias fortificações, e é conhecido como Demolidor.",
  str_monster_desc_2000101 = "Responsável por investigar a movimentação de Aurorians, e é conhecido como Batedor. Geralmente ataca Aurorians com outros Eclipsitas.",
  str_monster_desc_2000111 = "Servos do Mau-Olhado com fortes habilidades de ATQ e RES, às vezes são encontrados auxiliando Opressores.",
  str_monster_desc_2000121 = "Eclipsita especializado em detectar movimentações de Aurorians. Conhecido como Vidente, às vezes consegue detectar a grandes distâncias.",
  str_monster_desc_2000131 = "Exército de criaturas reptilianas cinza responsáveis por várias tarefas de combate básicas, são conhecidas como Limpadores.",
  str_monster_desc_2000141 = "Pequena criatura carregando uma caixa preta que transporta suprimentos da organização Eclipsita, conhecido como Mensageiro.",
  str_monster_desc_2000151 = "São lutadores Eclipsitas. Eles são poderosos em combate e podem comandar os Eclipsitas, são conhecidos como Oficiais.",
  str_monster_desc_2000161 = "Forte habilidade de camuflagem. Geralmente se infiltram em reuniões de Aurorians para assassinar, por isso são chamados de Assassinos.",
  str_monster_desc_2000171 = "Um dos \"Eclipsitas Materializados\". Geralmente na forma de uma pérola preta e é carregado por uma Sombra ou outros Eclipsitas. Costuma ser liberado em momentos críticos das batalhas para lutar.",
  str_monster_desc_2000181 = "Um dos \"Eclipsitas Materializados\". Geralmente na forma de uma pérola preta e é carregado por uma Sombra ou outros Eclipsitas. Costuma ser liberado em momentos críticos das batalhas para lutar.",
  str_monster_desc_2000211 = "São inadequados para a batalha, mas restauram PV de outros Eclipsitas. Dizem ter evoluído da Alma Sombria, às vezes são chamados de Curadores.",
  str_monster_desc_2000221 = "São inadequados para a batalha, mas podem criar espinhos que emergem do chão, teto e outras paredes de rocha para atacar passantes! Às vezes chamados de Espinhadores.",
  str_monster_desc_4000221 = "Sem poder de combate.",
  str_monster_desc_2000231 = "Seus pés podem absorver a Lúmina ao redor, tornando-se extremamente poderosos. Dizem que evoluíram dos Espectros Sombrios e também são conhecidos como \"Ingestores de Energia\".",
  str_monster_desc_2000241 = "Elite do Mau-Olhado com fortes habilidades de observação, dificultando a não detecção de Aurorians. Conhecidos como Videntes.",
  str_monster_desc_2000251 = "Os membros juniores que formam a base da força militar de Lumópolis são numerosos e amplamente ativos em Patrulhas.",
  str_monster_desc_2000261 = "Carregam o fardo de proteger a cidade o tempo todo sem reclamações. Sem descanso, são considerados como pilar da Guarda.",
  str_monster_desc_2000271 = "São guardas que também servem como batedores. Depois de passarem por treinamento especial, possuem mobilidade, destreza e agilidade extremamente altas.",
  str_monster_desc_2000281 = "Guardas armados com um escudo de defesa superior. Com a habilidade de aguentar batalhas difíceis, são fortes muralhas que protegem seus companheiros.",
  str_monster_desc_2000291 = "Lanceiros que tiveram treinamento de combate. Os ataques impactantes os tornam imparáveis no campo de batalha.",
  str_monster_desc_2000293 = "Lanceiros que tiveram treinamento de combate. Os ataques impactantes os tornam imparáveis no campo de batalha.",
  str_monster_desc_2000301 = "Eclipsitas encouraçados da Noite Branca, Área Sombria. Eram viciosos, mas depois de capturados, tornaram-se uma fonte de entretenimento.",
  str_monster_desc_2000302 = "A versão melhorada dos Eclipsitas encouraçados. Apesar de suas armaduras serem mais bonitas, eles não conseguem escapar do destino de serem uma fonte de entretenimento.",
  str_monster_desc_2000311 = "Gosta de lutar contra Aurorians com sua lâmina dupla e é muito habilidoso. Entretanto, raramente trabalha com outros Eclipsitas e é conhecido como Espadachim.",
  str_monster_desc_2000321 = "Evoluiu de um inseto veloz antes da guerra, se move rapidamente e é difícil de lidar. Conhecido como Perseguidor.",
  str_monster_desc_2000341 = "Saqueadores profissionais que vivem de roubar de civilizações antigas. Já que toda sua energia é usada para roubar, suas habilidades em combate são baixas e eles fogem ao encontrar inimigos.",
  str_monster_desc_2000351 = "Dizem que é uma versão mais fraca do Esmagador. Acredita-se que seja um Esmagador gravemente ferido que evoluiu após tratamentos.",
  str_monster_desc_2000411 = "Condicionado por energias fortes, alguns dos Eclipsitas do Mau-Olhado passaram por mutações estranhas.",
  str_monster_desc_2000421 = "Dito ser uma mutação Shadow Eclipsite, pode aumentar o ATK de outros Eclipsites.",
  str_monster_desc_2000431 = "Um Eclipsita especial criado pelos ancestrais dos vermes de areia. Seu Fluxo Escuro é muito instável e explode ao morrer.",
  str_monster_desc_2000441 = "Alguns Eclipsitas foram afetados por uma energia poderosa e evoluíram muito, recebendo alta resistência a um elemento específico.",
  str_monster_desc_2000442 = "Este tipo de Eclipsite acumulou tanta energia elementar que pode afetar o elemento de seu ambiente circundante.",
  str_monster_desc_2000451 = "Soldados de Lumópolis que foram enganados por Gertzurde, perderam suas habilidades de pensar e atacar após serem controlados pelos Eclipsitas. Eles marchavam até a batalha sob comandos de Gertzurde.",
  str_monster_desc_2000401 = "Eclipsitas de baixo nível não possuem inteligência. Eles só podem obedecer as ordens de seus invocadores e resistir a ataques.",
  str_monster_desc_2000491 = "Uma réplica criada por Eclipsitas de alto nível que possui habilidades especiais. Parece idêntica ao seu mestre a ponto de causar um caos substancial nos inimigos.",
  str_monster_desc_2000501 = "Estes Eclipsitas possuem um gancho especial para puxar alvos para ataques em grupo, então, cuidado!",
  str_monster_desc_2000511 = "Este tipo de Eclipsita possui um cristal cinza que emite um raio único que interrompe o fluxo de Lúmina do alvo, dificultando o controle.",
  str_monster_desc_2000521 = "Mutantes surgiram após alguns Eclipsitas devorarem os corpos de outros Eclipsitas. Eles podem liberar um campo de força que prende Lúmina e impossibilita seu fluxo.",
  str_monster_desc_2000531 = "Eclipsitas de Sonda Mutantes; dizem que desenvolveram uma visão de longa distância com um método poderoso e preciso de ataque a distância.",
  str_monster_desc_2000541 = "Eclipsitas Beligerantes Mutantes. Eles não só têm poder de combate aumentado, mas também a habilidade especial de corroer Lúmina.",
  str_monster_desc_2000551 = "Um novo tipo de Eclipsitas que apareceu no Território Secreto. Dizem que surgiram dos ressentimentos de uma raça anciã que foi exterminada por Eclipsitas. Essa é a única explicação para a fonte da habilidade de feitiçaria poderosa que eles conseguem controlar.",
  str_monster_desc_2000561 = "Eclipsitas Raros. Parecem Fantasmas flutuantes, se movem rápido e não podem ser acertados. Conhecidos como Espectros.",
  str_monster_desc_2000571 = "Testemunhas da explosão de poder da Schummer Branca. Eclipsitas formados da mistura de sua maldade e ódio. Impossibilitados de se mover, sua aura sombria cobre o céu o bastante para possuir poderosas habilidades de feitiçaria.",
  str_monster_desc_2000581 = "Diz ser uma variante do Abismo, um Eclipsita de baixo nível. Ele ouve os chamados de um Eclipsita de alto nível e pode se autodestruir com grande força. A única forma de evitar que isso aconteça é eliminá-lo antes de explodir.",
  str_monster_desc_2000601 = "Um Eclipsita especial que era pequeno e quase invisível a olho nu. Seu corpo inchou para o tamanho atual devido ao efeito de fortes emoções negativas.",
  str_monster_desc_2000602 = "Uma ilusão criada pela Luminática de Dawn, contém poder mágico.",
  str_monster_desc_2000611 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000701 = "Estes Eclipsitas especiais despertaram de um sono profundo. Eles são muitos, mas suas táticas são muito simples. Mas tome cuidado, pois eles têm a capacidade de se transformar!",
  str_monster_desc_2000702 = "Um castelo quebrado enterrado no fundo do mar. Sempre que seu sino toca, o Monarca Desolado libera sua ira sobre seus inimigos.",
  str_monster_desc_2000703 = "Este cavalo de guerra era um mero cadáver antes de ser despertado pelo Monarca Desolado. Mantendo a força e a lealdade de seu passado, ele ataca todos os inimigos de seu mestre sem questionar.",
  str_monster_desc_2000704 = "Ajudantes do rei, eles podem perceber passagens no vazio que outros não conseguem, e então avançar rapidamente para atacar.",
  str_monster_desc_2000705 = "Originalmente uma nobre, a vingança a trouxe para este mar, onde ela reviveu o lendário rei... No entanto, as forças das trevas que ela convocou também devoraram sua alma, transformando-a em Eclipsita.",
  str_monster_desc_2000711 = "Estes peões perdidos ganharam o poder do vazio. Embora suas táticas permaneçam simples, sua eficácia em combate aumentou bastante. Eles não podem ser subestimados.",
  str_monster_desc_2000712 = "Um castelo que esmaga tudo em seu caminho, seu sino torna-se o pior pesadelo de todos os inimigos.",
  str_monster_desc_2000713 = "Com um relincho terrível e cascos que sacodem a terra, quando esses cavalos ferozes entram na briga, a única coisa que pode detê-los é a morte.",
  str_monster_desc_2000714 = "Palavras de crueldade e corrupção os cercam... Cuidado com os ataques pelos lados.",
  str_monster_desc_2000715 = "Caroline... Louca de poder, se uniu ao vazio, ganhando um poder incalculável.",
  str_monster_desc_2000901 = "É dito que o Eclipse criou esse tipo novo de Eclipsita, capaz de implodir para destruir o terreno ao seu redor e rompar a defesa dos Aurorians.",
  str_monster_desc_2001001 = "Um Eclipsita que já morou nas profundezas do Território Secreto e se destaca no uso de ataques subterrâneos. Também é dito que é capaz de cavar passagens subterrâneas para outros Eclipsitas.",
  str_monster_desc_2001301 = "A poeira abaixou e a identidade de um conhecido inimigo alienígena ainda vai ser revelada. É hora de mostrar sua decisão.",
  str_monster_desc_2101301 = "Lacaios de Eclipsites, convocados por Eclipsites de alto nível.",
  str_monster_desc_4001301 = "Lacaios de Eclipsites, convocados por Eclipsites de alto nível.",
  str_monster_desc_2001401 = "Os tentáculos simbióticos de um Kittypus, eles transferem qualquer dano recebido diretamente para seu hospedeiro.",
  str_monster_desc_2900271 = "Este tipo de Eclipsita passou por uma mutação estranha. Dizem que seu poder de combate é comparável ao de um Eclipsita de alto nível. É líder de todos os Eclipsitas encouraçados e tem PV muito alto.",
  str_monster_desc_2900262 = "Uma Aurorian corrompida por forças sombrias poderosas. Perdeu toda a sua autoconsciência e é extremamente perigoso.",
  str_monster_desc_2900263 = "No passado, Eve foi enlouquecida pelo “tratamento” da mulher misteriosa que causou a perda de controle de seu poder e o incêndio “daquela” Subcidade. Raiva e culpa vão partindo seu coração à medida que a tragédia se repete várias vezes... Acalme o ódio dela agora.",
  str_monster_desc_2900264 = "Uma garota misteriosa que você encontrou em Ravinha Olho Rubro. Sem motivo ela “ordenou” aos Eclipsitas que levassem Eve.",
  str_monster_desc_2900281 = "Um tipo de Eclipsita que tem pouca inteligência e não tem vontade própria. Seu propósito é desconhecido e pode-se dizer que é associado à Crise Darkover. Conhecido como Presságio Darkover.",
  str_monster_desc_2900391 = "Apesar de se mover lentamente, tem forte DEF e pode lançar Bombas Abissais com poderes esmagadores. Conhecido como Transportador.",
  str_monster_desc_2900401 = "Originalmente um Celestita, mas se uniu ao Eclipse e possui poderes melhorados extraordinários.",
  str_monster_desc_2900402 = "Originalmente um Celestita, mas se uniu ao Eclipse e possui poderes melhorados extraordinários.",
  str_monster_desc_2900403 = "Originalmente um Celestita, mas se uniu ao Eclipse e possui poderes melhorados extraordinários.",
  str_monster_desc_2900411 = "Originalmente membro dos Guardiões de Lumópolis. Por causa de Shelt, estava decidido a destruir Lumópolis por ela.",
  str_monster_desc_2900421 = "Após a derrota de Nozard, seu corpo foi recuperado por uma organização desconhecida e transformado experimentalmente em um monstro terrível.",
  str_monster_desc_2900422 = "Um grande Eclipsite que se assemelha a um dragão gigantesco, à espreita no Blazing Tooth Canyon.",
  str_monster_desc_2900431 = "Um gigante verme de areia ancião tem ocupado o lugar desde que ele foi destruído. Recentemente, após acordar de seu longo cochilo, começou a atacar todos os invasores.",
  str_monster_desc_2900441 = "O Eclipse transformou Umbrahulk, deixando-o mais poderoso. Desde então, tem sido contratado pelo Eclipse para explorar as ruínas da Torre e lidar com várias contingências.",
  str_monster_desc_2900451 = "Originalmente um monstro parecido com fantasma, começou a se desenvolver devido ao poder da Luz após entrar na terra. Pode criar várias ilusões com luz refratada no campo de batalha.",
  str_monster_desc_2900452 = "Um portal criado pela Forosão de Eclipsitas. Usado para se esconder e emboscar quando encontrar a fraqueza de um inimigo.",
  str_monster_desc_2900501 = "Evoluiu do Siforbe, absorve tanta Lúmina que é incapaz de controlar a cor de luzes dos arredores. Também pode usar seu mana para absorver Aurorians próximos para atacá-los.",
  str_monster_desc_2900601 = "Mutantes que surgiram após o Solmorfo da organização Eclipsita absorver o poder da Torre. De repente eles podem lançar a Lúmina que absorveram para causar uma poderosa expulsão letal.",
  str_monster_desc_2900611 = "Mutantes criados pela Organização Eclipsita ao usar as sobras de Eclipsitas de alto nível como Fantasmas. Eles têm habilidades de divisãos poderosas e só podem ser destruídos ao derrotar todos os clones.",
  str_monster_desc_2900641 = "Vários Caracalitas combinados e modificados em um Eclipsita de alto nível, do qual a maestria do Eclipsium é ainda mais poderosa. É extremamente difícil de lidar por conta de sua técnica especial de prender Lúmina.",
  str_monster_desc_2900651 = "Dizem que quando o gene de Tabaad é injetado em um Eclipsita poderoso, um Eclipsita de alto nível parecido com Tabaad emerge com mais habilidades poderosas e obediência inquestionável.",
  str_monster_desc_2900661 = "O outro novo brinquedo de Forsakin. Ao contrário do Tédio prévio, ele possui uma técnica terrível que pode corroer a Lúmina, além de seu grande poder. Nunca deve ser encarado brandamente.",
  str_monster_desc_2900671 = "Após as sementes dentro do seu corpo terem atingido crescimento parasitário, sua forma, que absorveu grandes quantidades de energia, tornou-se completamente diferente do passado. Até sua aparência mudou.",
  str_monster_desc_2900681 = "Eclipsitas Tremeluzentes Mutantes. Extremamente ágeis, podem parecer com um fantasma que vai e vem sem deixar rastros e meios ordinários não conseguem feri-lo.",
  str_monster_desc_2900701 = "Robô deixado para trás por civilizações antigas. Com projeto exclusivo, pode continuar trabalhando mesmo parcialmente destruído. É extremamente difícil de lidar.",
  str_monster_desc_2900711 = "Robô apareceu depois de a separação de T-1024. Tentará encontrar outros T-256s e então formar outro T-1024.",
  str_monster_desc_2910711 = "Um robô funcional com origens desconhecidas. Suas capacidades ofensivas não devem ser subestimadas.",
  str_monster_desc_29107141 = "\"Bip Bip!\"",
  str_monster_desc_29107111 = "\"Beep! Bzz!\"",
  str_monster_desc_2800241 = "“O que está olhando? Não espere encontrar informações sobre mim aqui. Nem Aurorians e nem Celestitas conseguem entender o nível SUPERIOR de uma busca...”",
  str_monster_desc_2900801 = "Um antigo rei que ficou enterrado nas profundezas do oceano por eras. Despertado pela Rainha Ardilosa, ele jurou prender seus inimigos no vazio para sempre.",
  str_monster_desc_2900811 = "O enfurecido rei antigo controla e brinca com todos e quaisquer intrusos até que a morte finalmente os leve.",
  str_monster_desc_2900911 = "Supostamente Eclipsitas de alto nível que participaram de diversas batalhas ferozes. Em números desconhecidos e possuindo a habilidade de voar, eles despertaram de seu sono e estão prontos para causar um novo pesadelo nos Aurorians.",
  str_monster_desc_2900912 = "Esse Eclipsita segue Hylingerr e pode ajudá-lo em batalha.",
  str_monster_desc_2901001 = "Originalmente um nobre de Lumópolis. Depois de ser banido da cidade, o ressentimento por sua antiga nação aumentou, a ponto de ele desertar para o Eclipse e tentar derrubar a liderança de Lumópolis. Quando seu plano falhou, ele desceu ainda mais fundo na insanidade, seu ódio crescente alimentando seu poder...",
  str_monster_desc_2901101 = "Incapaz de superar seu medo e desesperado para concretizar sua ambição, ele passa por uma perigosa transformação temporária sem pensar duas vezes, transformando-se nessa criatura aterrorizante.",
  str_monster_desc_2901201 = "Um antigo herói que se tornou um Eclipsita para lutar contra eles. Ele agora se tornou um monstro irracional.",
  str_monster_desc_2901300 = "Eclipsita Enigmático de origem desconhecida. Sua presença não parece se adequar à realidade que conhecemos.",
  str_monster_desc_2901301 = "A poeira abaixou e a identidade de um conhecido inimigo alienígena ainda vai ser revelada. É hora de mostrar sua decisão.",
  str_monster_desc_2901401 = "Um companheiro especial de Gretel. Geralmente quieto e plácido, mas conhecido por enlouquecer em batalha. Aproxime-se com cautela.",
  str_monster_desc_2901501 = "Um companheiro especial de Gretel. Brincalhão e enérgico, gosta particularmente de lutar contra um grupo de inimigos.",
  str_monster_desc_2901601 = "Um companheiro especial de Gretel. Tem um par de pernas extremamente fortes que podem repelir qualquer inimigo.",
  str_monster_desc_2901701 = "Um companheiro especial de Gretel. Assemelha-se a um gato com muitas pernas... É fofo, mas de alguma forma perturbador.",
  str_monster_desc_2901801 = "Os moradores da Cidade Perdida, cujas identidades permanecem um mistério, parecem se considerar os donos deste lugar.",
  str_monster_desc_2901901 = "Ex-chefe do Wisp que se dedica a combater os invasores da Ilha das Nuvens.",
  str_monster_desc_2901911 = "A frenética Nagi atacará qualquer um que ela perceba como um intruso.",
  str_monster_desc_2902001 = "Um tirano que veio de outra ilha do Extremo Oriente para governar a Ilha das Nuvens, e ele fará qualquer coisa para declarar soberania sobre ela.",
  str_monster_desc_2902101 = "Devido à sua obsessão, ele se transformou em um homem hediondo e prometeu eliminar todos os que resistissem.",
  str_monster_desc_2902201 = "Um poderoso Eclipsite que viveu sozinho nas ruínas por muitos anos. Completamente insano, ele ataca todos os forasteiros.",
  str_monster_desc_2902202 = "Um ex-soldado Illumina que se transformou em um Eclipsite sob a influência do Darkflow. O ódio consumiu toda a sua sanidade e roubou toda a sua antiga glória.",
  str_monster_desc_2902301 = "A IA na base subterrânea de Eraveil que guarda a base há milhares de anos e é responsável por limpar todos os inimigos invasores.",
  str_monster_desc_2902401 = "A IA na base subterrânea de Eraveil que parece grande e pesada, é Claudiaamigo do.",
  str_monster_desc_2902501 = "O mordomo da medalha de ouro da Andersen que não deixa manchas, lixo ou vermes sem vigilância.",
  str_monster_desc_2902601 = "Diz-se ser o Phantom\"irmão\" de Eternal Night. É capaz de usar táticas diferentes de acordo com a hora do dia e é extremamente difícil de lidar.",
  str_monster_desc_2902701 = "“O que está olhando? Não espere encontrar informações sobre mim aqui. Nem Aurorians e nem Celestitas conseguem entender o nível SUPERIOR de uma busca...”",
  str_monster_ability_2900063 = "Ataca alvos à frente com suas garras gigantescas e pode voar para bombardear áreas específicas do chão.",
  str_monster_ability_2900141 = "Com habilidades em ataque de curto alcance, seus ataques atordoam o alvo com a habilidade de convocar o Carniceiro. Depois de ficar Raivoso, seus ataques normais viram ataques duplos com alcance melhorado e ele pode convocar a Alma Sombria e Carniceiro ao mesmo tempo.",
  str_monster_ability_2900142 = "Excelente em combate de curta distância, seus ataques são capazes de atordoar alvos. Tem a capacidade de convocar outros Eclipsites. Enquanto estiver no modo Rabid, restaura 20% de sua saúde máxima; depois que o modo Rabid termina, seus ataques normais podem atacar duas vezes e seu alcance de habilidade é bastante aumentado.",
  str_monster_ability_2900181 = "Com habilidades em ataque a distância que atordoam o alvo e convocam a Alma Sombria. Quando está Raivosa, seus ataques normais acertam em dobro com alcance melhorado, e ela pode convocar a Alma Sombria e Carniceiro ao mesmo tempo.",
  str_monster_ability_2900182 = "Excelente em combate de longo alcance, seus ataques são capazes de repelir alvos. Tem a capacidade de convocar outros Eclipsites. Enquanto estiver no modo Rabid, restaura 20% de sua saúde máxima; depois que o modo Rabid termina, seus ataques normais podem atacar duas vezes, e seu alcance de habilidade é bastante aumentado.",
  str_monster_ability_2900201 = "É bom em usar seu grande corpo para atacar alvos à sua frente. Ele entra no solo e causa dano a alvos próximos ao emergir.",
  str_monster_ability_2900211 = "Seu ataque de curto alcance acompanha um empurrão e tem a habilidade de convocar Pedras para atacar. Alvos atingidos serão empurrados para áreas nas quais surgem novas Pedras. Pode lançar um ataque em tela cheia e o dano causado é determinado pelo número de Pedras.",
  str_monster_ability_2900221 = "Seu ataque normal vem com um empurrão. Pode converter a área de combate em Lúmina de seu próprio elemento e libertar uma ampla gama de ataques baseados no próprio elemento: Fogo - Dano em área amplo com efeitos de Incêndio, Trovão - Dano de tela cheia com Pestespinhos aleatórios.",
  str_monster_ability_2900231 = "Ataques de curto alcance de Filex vêm com empurrão e seus ATQ da Habilidade atordoam alvos.",
  str_monster_ability_2900232 = "Vani pode usar Energia para golpear a distância e recuperar PV para Filex.",
  str_monster_ability_2900241 = "Joga Munição Incendiária na área de batalha, fazendo com que unidades passantes recebam Queimaduras. Pode atacar um alvo e atordoar ao acertar, usando aura da espada para atacar duas fileiras de alvos em frente.",
  str_monster_ability_2900251 = "Causa um ataque em área em forma de cruz e convoca um clone para lutar ao seu lado. Após clonar, absorve o PV do clone anterior para restaurar o próprio PV. Quando seu PV está menor que 50%, seus ataques normais viram ataques duplos, ataques em área tornam-se ataques de tela cheia.",
  str_monster_ability_2000011 = "Unidade de combate principal dos Eclipsitas, habilidade em ataque corpo a corpo com garras.",
  str_monster_ability_2000071 = "Um Eclipsita enorme responsável pela destruição de várias fortificações e bastante capaz de demolir construções.",
  str_monster_ability_2000101 = "Um batedor Eclipsita que é capaz de usar a luz emitida pela boca para atacar inimigos a distância.",
  str_monster_ability_2000111 = "É conhecido pelo seu uso de barreiras para resistir a ataques inimigos.",
  str_monster_ability_2000121 = "Um Eclipsita com um baixo nível de habilidades de invocação. Incapaz de se mover por conta própria, luta invocando Opressor.",
  str_monster_ability_20001211 = "Um Eclipsita com um baixo nível de habilidades de invocação. Incapaz de se mover por conta própria, luta invocando Eclipsitas.",
  str_monster_ability_20001221 = "Um Eclipsita com um baixo nível de habilidades de invocação. Incapaz de se mover por conta própria, luta invocando Magicaninos.",
  str_monster_ability_20001231 = "Um Eclipsite com habilidades de invocação de baixo nível. Incapaz de se mover por conta própria e luta invocando Darkwasp.",
  str_monster_ability_20001241 = "Um Eclipsite com habilidades de invocação de baixo nível. Incapaz de se mover sozinho e luta invocando Dreadblades.",
  str_monster_ability_20001251 = "Um Eclipsite com habilidades de invocação de baixo nível. Incapaz de se mover sozinho e luta invocando Slashers.",
  str_monster_ability_20001261 = "Um Eclipsite com habilidades básicas de convocação. Incapaz de se mover por conta própria e luta convocando Prober.",
  str_monster_ability_2000131 = "Um Eclipsita de baixo nível, só é capaz de realizar ataques básicos baseados em instinto.",
  str_monster_ability_2000141 = "Um Eclipsita com ATQ comum, que é responsável por reunir suprimentos.",
  str_monster_ability_2000151 = "Especialista em usar seus dois punhos gigantes para lutar. Sua habilidade de Golpe de Martelo causa dano em área e atordoa alvos.",
  str_monster_ability_2000161 = "Use sua lança para atacar o alvo e receber a habilidade para invocar Alma Sombria.",
  str_monster_ability_2000171 = "Eclipsitas Materializados Tipo II: Eclipsita de Cura. Geralmente na forma de pérola preta e é hábil para curar outros Eclipsitas quando é libertado.",
  str_monster_ability_2000181 = "Eclipsitas Materializados Tipo I: Eclipsitas a Distância. Geralmente, na forma de pérola preta. Hábil para engajar em batalhas quando libertado, mas o poder de combate é mais fraco.",
  str_monster_ability_2000211 = "Um Eclipsita com a habilidade de curar, responsável pela restauração do PV de outros Eclipsitas.",
  str_monster_ability_2000221 = "Não é adequado para batalhas, mas pode fazer espinhos emergirem do chão para atacar passantes.",
  str_monster_ability_4000221 = "Normalmente, monstros desse tipo usam espinhos no chão para atacar os transeuntes. Mas a habilidade deste em particular parece ser diferente de alguma forma.",
  str_monster_ability_2000231 = "Um Eclipsita de alcance cuja principal habilidade de combate é se fortalecer ao absorver Lumina. É especialista em ataques de longo alcance e, embora seu poder de batalha original seja insuficiente, após absorver Lumina, seu poder de batalha melhora significativamente.",
  str_monster_ability_2000241 = "Um Eclipsita com habilidades de invocação intermediárias. Incapaz de se mover por conta própria, luta usando Sondas que possuem ataques a distância.",
  str_monster_ability_20002411 = "Um Eclipsita com poderosas habilidades de invocação. Pode invocar vários tipos de Eclipsitas para lutar.",
  str_monster_ability_20002421 = "Um Eclipsita com habilidades de invocação intermediárias. Luta invocando Terrilâminas que possuem habilidades poderosas de combate.",
  str_monster_ability_20002422 = "Um Eclipsita com habilidades de invocação intermediárias. Luta invocando Terrilâminas que possuem habilidades poderosas de combate e Magicaninos com capacidades defensivas incríveis.",
  str_monster_ability_20002423 = "Um Eclipsite com habilidades de invocação intermediárias. Ele luta convocando Dreadblades que possuem poderosas habilidades corpo a corpo e Vinesmark que lança ataques mortais à distância.",
  str_monster_ability_2000251 = "Os membros júnior da base militar de Lumópolis. Numerosos, seu modo de combate principal é o uso de armas equipadas para ataques a longa distância.",
  str_monster_ability_2000261 = "Guardas mecânicos de Lumópolis. Ao encontrar inimigos, eles lutam criando soldados espada longa.",
  str_monster_ability_2000271 = "Batedores de elite de Lumópolis que instantaneamente se movem para outro local após atacar o alvo. Sua mobilidade e destreza faz com que sejam um alvo difícil de atingir em um combate regular.",
  str_monster_ability_2000281 = "Guardas armados com escudo, com DEF superior. O escudo de suas armas serve como defesa e como arma de curto alcance.",
  str_monster_ability_2000291 = "Lanceiros que passaram por treinamento têm grande vontade de lutar e aptidão para combate de curto alcance.",
  str_monster_ability_2000293 = "Lanceiros que passaram por treinamento têm grande vontade de lutar e aptidão para combate de curto alcance.",
  str_monster_ability_2000301 = "Eclipsitas de transporte normais. Transportam envios leves de Noitium. Derrote-os para conseguir o dinheiro.",
  str_monster_ability_2000302 = "Eclipsitas de transporte melhorados. Transportam envios grandes de Noitium. Derrote-os para conseguir o dinheiro.",
  str_monster_ability_2000311 = "Um Eclipsita novo que provavelmente evoluiu de outros Eclipsitas. É bom com lâminas duplas e lança ataques duplos em seus alvos quando é confrontado.",
  str_monster_ability_2000321 = "Um Eclipsita do tipo inseto que se move rápido, ordenado a buscar e caçar seus alvos de perto.",
  str_monster_ability_2000341 = "Um grande número de bandidos que são bons em escapar.",
  str_monster_ability_2000351 = "Um Eclipsita poderoso que pode empurrar alvos com seus ataques.",
  str_monster_ability_2000411 = "Um Eclipsita mutante especializado em ataques à distância. Quando seu elemento é Fogo, ele pode invocar a Chuva Ardente para queimar os alvos atingidos. Quando seu elemento é Trovão, ele pode invocar o Poder do Relâmpago para paralisar os alvos atingidos.",
  str_monster_ability_2000421 = "Especialista em ataques a distância e concede buff a Eclipsitas próximos em batalha.",
  str_monster_ability_2000431 = "Especialista em combate corpo a corpo. Quando está à beira da morte, se move em direção ao jogador e detona, causando dano a todos os alvos próximos.",
  str_monster_ability_2000441 = "Ataca o alvo com ataques corpo a corpo. Os efeitos dos ataques aurorianos que não contrariam seu elemento serão bastante reduzidos.",
  str_monster_ability_2000442 = "Lança ataques corpo a corpo contra seu alvo e converte todas as peças ao longo de seu caminho de movimento em peças do mesmo elemento que ele.",
  str_monster_ability_2000451 = "Causa debuff em seus inimigos.",
  str_monster_ability_2000501 = "Pode puxar alvos distantes em sua direção e causar dano alto a alvos em 1 círculo ao redor.",
  str_monster_ability_2000511 = "O alcance do ataque é pequeno. Entretanto, seus ataques causam perda de energia em Aurorians, o que aumenta o número de rodadas de recarga das Habilidades Ativas.",
  str_monster_ability_2000521 = "Pode bloquear elementos de casas. Ao acertar um alvo, elementos de casas ao redor do alvo serão bloqueados. Após mover, bloqueará elementos das casas ao redor de si mesmo.",
  str_monster_ability_2000531 = "Eclipsites que são extremamente bons em atacar à distância. Quanto mais longe o alvo atacado estiver da Vinesmark, mais dano o alvo receberá.",
  str_monster_ability_2000541 = "Os ataques poderosos de Doomskull podem esmagar ladrilhos dentro de uma grande área.",
  str_monster_ability_2000551 = "Eclipsitas raros com a habilidade de amaldiçoar. Lançará uma maldição sobre o alvo. O Aurorian amaldiçoado não pode usar Habilidades Ativas ou ser selecionado como Capitão por várias rodadas.",
  str_monster_ability_2000561 = "Um caçador de longa distância que muda sua posição antes de atacar a cada rodada.",
  str_monster_ability_2000571 = "Demônios controlados pela Schummer. Eles intervirão na mobilização de Aurorians. Se a Hora da Aurora não puder ser acionada por várias rodadas, os Aurorians imergirão na escuridão.",
  str_monster_ability_2000581 = "Um Eclipsita invocado por Sem Formas, esse monstro irracional lança ataques suicidas em seus inimigos. Ele explode se não for destruído após um certo número de rodadas, destruindo sua localização atual.",
  str_monster_ability_2000582 = "Um Eclipsite convocado por Formless, este monstro irracional lança ataques suicidas em seus inimigos. Explode se não for destruído dentro de um certo número de rodadas, convocando uma Área de Alarme.",
  str_monster_ability_2000601 = "Um Eclipsita sem habilidade de combate, mas pode se prender a um Eclipsita que está em 1 círculo ao seu redor. Depois de se prender, fornece um Escudo ao Eclipsita e melhora seus ataques.",
  str_monster_ability_2000602 = "Prende-se à Dawn e recupera seu PV quando está em 1 círculo ao redor de Dawn.",
  str_monster_ability_2000611 = "Um Eclipsite sem habilidade de combate, mas pode se conectar a um Auroriano dentro de 1 aglomerado ao redor de si mesmo. Uma vez anexado, ele continuará a reduzir o valor de sanidade do auroriano.",
  str_monster_ability_2000701 = "Depois de se mover, causa dano aos inimigos em 4 casas em forma de cruz ao redor. Ao chegar na borda do Tabuleiro de Alquimia, eles são promovidos a Torre Furiosa, Cavalo Caído, Bispo Eclipse ou Rainha Ardilosa, de acordo com sua ordem de chegada.",
  str_monster_ability_2000702 = "Só pode mover-se horizontal ou verticalmente a partir da sua posição. Após se mover, causa dano a alvos dentro de 1 círculo ao redor. Ao colidir com um alvo enquanto se move, causará mais dano a esse alvo e o empurrará para a borda do tabuleiro.",
  str_monster_ability_2000703 = "Só pode pular diagonalmente. Após pousar, causa dano aos inimigos em 4 casas ao redor, em uma forma de cruz. Se houver um alvo na casa em que pousar, causará dano forte ao alvo e o atordoará, jogando-o para trás.",
  str_monster_ability_2000704 = "Só pode se mover diagonalmente. Causa dano a alvos dentro de seu alcance máx. em forma de cruz.",
  str_monster_ability_2000705 = "Causa dano igual a uma porcentagem do PV máximo do alvo a alvos dentro de seu alcance máximo em forma radial.",
  str_monster_ability_2000711 = "Depois de se mover, causa dano aos inimigos em 4 casas em forma de cruz ao redor. Ao chegar na borda do Tabuleiro de Alquimia, eles são promovidos a Torre Furiosa - RAM, Cavalo Caído - CHARGE, Bispo Eclipse - EX ou Rainha Ardilosa, de acordo com sua ordem de chegada.",
  str_monster_ability_2000712 = "Só pode mover-se horizontal ou verticalmente a partir de sua posição. Após se mover, causa dano a alvos dentro de 2 círculos ao redor. Ao colidir com um alvo enquanto se move, causará mais dano a esse alvo e o empurrará para a borda do tabuleiro.",
  str_monster_ability_2000713 = "Só pode pular diagonalmente. Após pousar, causa dano em 1 círculo ao redor. Se houver um alvo na casa em que pousar, causará dano forte ao alvo e o atordoará, jogando-o para trás.",
  str_monster_ability_2000714 = "Só pode se mover diagonalmente. Causa dano a alvos dentro de seu alcance máx. em forma de cruz e reduz sua DEF.",
  str_monster_ability_2000715 = "Causa dano igual a uma porcentagem do PV máximo do alvo, em alvos dentro de seu alcance máximo em forma radial. Se não houver alvos nas 8 direções ao redor dela, ganha uma barreira defensiva.",
  str_monster_ability_2000901 = "Se autodestrói após a contagem chegar a zero, destruindo as casas em sua localização atual e tornando-o inutilizável.",
  str_monster_ability_2001001 = "Destaca-se na utilização de terreno destruído. É capaz de causar muito dano às unidades em torno das casas quebradas.\nQuando Aurorians passam por casas quebradas, seu contador de combo não aumenta.",
  str_monster_ability_2001301 = "Com habilidade forte de ATQ e normalmente oculto no campo. Não pode ser atacado a menos que se revele durante a Hora da Aurora.",
  str_monster_ability_2001341 = "Causa muito dano e é invencível enquanto estiver em ladrilhos verdes.",
  str_monster_ability_2101301 = "Eclipsite Minion não ataca e normalmente fica escondido no campo de batalha. Ele não pode ser atacado a menos que se revele durante o Aurora Time.",
  str_monster_ability_4001301 = "Causa muito dano.",
  str_monster_ability_2001401 = "Sensível e manso, ele evitará ataques aurorianos a todo custo.",
  str_monster_ability_2900271 = "Um Eclipsitas encouraçado melhorado, que é capaz de usar ataques de tela cheia a distância.",
  str_monster_ability_2900262 = "Incapaz de se mover por conta própria, mas tem uma ampla gama de ataques. Pode absorver matéria escura e transformá-la em barreira. Também pode atacar e empurrar três fileiras de inimigos à sua frente.",
  str_monster_ability_2900263 = "Incapaz de se mover por conta própria, mas tem uma ampla gama de ataques. Pode absorver matéria escura e transformá-la em barreira. Também pode atacar e empurrar três fileiras de inimigos à sua frente.",
  str_monster_ability_2900264 = "Causa dano a inimigos em 2 círculos ao redor e inimigos na tela cheia. Pode se transformar em uma Fada Dawn para recuperar PV.",
  str_monster_ability_2900281 = "Pode invocar um sinal e restaurar o PV do sinal enquanto recebe redução de dano baseada no número de sinais ao redor. Suas habilidades têm ataque a distância em cruz e o dano e distância das habilidades recarregáveis são baseados no número de sinais.",
  str_monster_ability_2900391 = "Incapaz de se mover por conta própria e somente é vulnerável a Dano de Bomba. Pode invocar bombas, e depois de carregado, invocará bombas continuamente e lançará ampla Habilidade de Dano de Área.",
  str_monster_ability_2900401 = "Resistente a ataques físicos e pode resistir ao dano de Ataques Normais. Causa dano a alvos à frente e pode lançar ataques em tela cheia. Capaz de invocar Cristais de Raio.",
  str_monster_ability_2900402 = "Resistente a danos de Ataque Normal. Causa dano a alvos em uma faixa em forma de cruz ou em tela cheia, invocando raios em áreas específicas periodicamente. Causa dano contínuo em tela cheia após se tornar Raivoso.",
  str_monster_ability_2900403 = "É bom em ataque a distância e AdE e pode sincronizar seu PV. Schummer de menor PV sincronizará seu PV com Schummer de maior PV no campo de batalha, até 30% por restauração.",
  str_monster_ability_2900411 = "Invoca reforços na batalha. O alcance do ataque agora é o campo inteiro e os ataques adicionam um debuff aos inimigos atingidos, diminuindo a defesa deles. Ataques normais enfurecidos acertarão duas vezes.",
  str_monster_ability_2900421 = "Pode atacar áreas específicas e invocar Magicanino para ajudar, causando dano a alvos à frente ou por toda a tela.",
  str_monster_ability_2900422 = "Causa dano aos alvos à sua frente ou em toda a tela e repele as unidades inimigas. Capaz de invocar Spikepests.",
  str_monster_ability_2900431 = "É bom em usar seu grande corpo para atacar alvos à frente dele. Ele entra no solo e causa dano a alvos próximos ao emergir. Também pode invocar Insetos Explosivos.",
  str_monster_ability_2900441 = "Seu ataque normal acompanha um empurrão, pode invocar um Cristal Duplicado para criar 1 Pedra Elemental por rodada. Pode consumir todas as Pedras para lançar um ataque ao alvo e seu dano é determinado pelo número de Pedras.",
  str_monster_ability_2900451 = "Esconde-se na Lumiwall mais distante do jogador; ataques podem mudar o elemento da casa durante sua rota do ataque.",
  str_monster_ability_2920451 = "Cria ilusões ao redor dos alvos após abalroá-los. Cada Lumiwall reduz o dano recebido pelo Phorosion, assim como seu ATK; enquanto Despertos, Lumiwalls criam ainda mais ilusões a cada rodada.",
  str_monster_ability_2900452 = "Esconde-se na Lumiwall mais distante do jogador; ataques podem mudar o elemento da casa durante sua rota do ataque.",
  str_monster_ability_2900501 = "Possui a habilidade para mudar a Casa do Tabuleiro de Alquimia. Alvos atingidos por sua habilidade serão puxados.",
  str_monster_ability_2900601 = "Possui ataques de longa distância. Pode puxar alvos distantes, mudar os elementos da casa de alvos atingidos e casas distantes ao redor.",
  str_monster_ability_2900611 = "Incapaz de se mover, mas tem habilidade em ataques em forma de cruz e de longa distância; ataques causam perda de energia de Aurorians, o que aumenta o número de rodadas de recarga de Habilidades Ativas; se divide ao morrer.",
  str_monster_ability_2900641 = "Habilidade em ataques a longa distância. Prende os elementos das casas ao redor após se movimentar e possui a habilidade de contra-ataque, prendendo os elementos das casas em 1 círculo ao redor de Aurorians cada vez que eles usam uma Habilidade Ativa.",
  str_monster_ability_2900651 = "Habilidade em ataques a longa distância; ataques de longuíssima distância causam mais dano a alvos distantes; pode invocar Marcavinha para ajuda.",
  str_monster_ability_2900661 = "Bomba Destruidora esmagará todas as casas no campo. Este ataque pode empurrar o alvo. Pode contra-atacar. Ela destruirá 2 casas aleatórias no campo toda vez que um Aurorian lançar uma Habilidade Ativa.",
  str_monster_ability_2900662 = "Bomba Destruidora esmagará todas as casas no campo. Este ataque pode empurrar o alvo.",
  str_monster_ability_2900671 = "Pode usar ataques em forma de cruz ou de tela inteira e invocar raios. Quando enfurecido, ele ganha a habilidade de empurrar os alvos para trás e causar dano na tela inteira e dano de longo alcance.\nObservação: quando todos os Demônios de Schummer forem ativados, ele lançará uma habilidade de tela inteira que aniquilará todos os Aurorians.",
  str_monster_ability_2900681 = "Invoca Nulidade, que pode se autodestruir. Pode se teletransportar para longe de você, para as bordas do Tabuleiro de Alquimia, para atacar.",
  str_monster_ability_2900701 = "Ataques causam efeito de empurrão no alvo; refletirá dano se for atacado durante sua defesa; possui alto poder de recuperação; invoca um T256 ao morrer.",
  str_monster_ability_2900711 = "Uma construção mecânica antiga que apareceu após a divisão do T-1024. Possui capacidade inata de ataque a distância.",
  str_monster_ability_2910711 = "Um robô funcional com origens desconhecidas e capaz de fazer ataques normais à distância.",
  str_monster_ability_29107141 = "\"Bip Bip!\"",
  str_monster_ability_29107111 = "\"Beep! Bzz!\"",
  str_monster_ability_2800241 = "Parece ser um oponente muito forte com poderes desconhecidos que vão empurrar o alvo em todas as rodadas.",
  str_monster_ability_2900801 = "Capaz de comandar os Peões Perdidos a causar dano aos alvos em 1 círculo ao redor. Pode empurrar alvos em torno de si mesmo e lançar ataques na tela inteira.",
  str_monster_ability_2900811 = "Capaz de comandar os Peões Perdidos a causar dano aos alvos em 1 círculo ao redor. Pode empurrar alvos em torno de si mesmo e lançar ataques na tela inteira.",
  str_monster_ability_2900911 = "Pode causar dano a alvos na frente dele. Possui a habilidade de rastrear os alvos.",
  str_monster_ability_29009111 = "Pode causar dano a alvos em uma grande área à sua frente e tem a capacidade de rastrear alvos. Pode invocar Tentaclaws que podem afetar a Sanidade dos Aurorianos.",
  str_monster_ability_2900912 = "Ataca onde o jogador estava localizado na rodada anterior. Seus ataques em área causam dano aos alvos e os empurram. O monstro será ressuscitado diversas rodadas após ser derrotado.",
  str_monster_ability_2901001 = "Ataca e repele os inimigos ao redor de ladrilhos danificados. Carrega em unidades inimigas dentro de seu alcance de ataque e as repele. Pode danificar telhas repetidamente se teletransportando.",
  str_monster_ability_2901101 = "Pode atacar Aurorians a distância e possui a habilidade de controlar Eclipsitas.",
  str_monster_ability_2901201 = "Possui um poder estranho e assustador. Quando o PV de Claymore cai para um certo valor, ele ______.",
  str_monster_ability_2901300 = "Tem uma habilidade de redução de dano poderosa. Só pode causar dano durante a Hora da Aurora.",
  str_monster_ability_2901301 = "Tem uma habilidade de redução de dano poderosa. Só pode causar dano durante a Hora da Aurora. Capaz de invocar Lacaios Aterrorizadores com forte ATQ para ajudar.",
  str_monster_ability_2901341 = "Tem DEF extremamente forte e pode convocar Minions Fearmonger com forte ATK para ajudá-lo. No entanto, a DEF do Fearmonger também diminui quando os lacaios do Fearmonger morrem.",
  str_monster_ability_2901401 = "Os ataques invocam um tipo especial de Spikepest que não pode ser morto usando ataques de limpeza de tabuleiro. Se os jogadores ficarem muito próximos ao atacar, seu dano contra mobs é significativamente reduzido.",
  str_monster_ability_2901501 = "Excreta uma substância venenosa, de modo que uma parte de seus ataques corpo a corpo paralisará o jogador. Se os jogadores ficarem muito próximos ao atacar, seu dano contra mobs é significativamente reduzido.",
  str_monster_ability_2901601 = "Ironstomp marcha pesadamente pelo campo de batalha, causando danos devastadores a qualquer peça em seu caminho.",
  str_monster_ability_2901701 = "Kittypus libera seus tentáculos, causando dano massivo aos Aurorianos. (Lembre-se: os tentaclaws de Kittypus transferem todos os danos recebidos para seu hospedeiro!)",
  str_monster_ability_2901801 = "Mantém distância dos alvos e é capaz de convocar e controlar armadilhas para se ajudar em combate.",
  str_monster_ability_2901901 = "Capaz de fazer diferentes escolhas táticas com base na distância dos Aurorianos.",
  str_monster_ability_2901911 = "Quando frenético, a esgrima de Castellan é aprimorada e causa uma enorme quantidade de dano.",
  str_monster_ability_2902001 = "Astuto e traiçoeiro, ele é habilidoso em ataques à distância e, quando o inimigo se aproxima, ele foge e deixa uma sombra para trás. A cada rodada, ele pode conjurar um número específico de fantasmas para ajudar na batalha.",
  str_monster_ability_2902101 = "Conjure um grande número de fantasmas e libere diferentes habilidades poderosas com base na distância entre os Aurorianos e o inimigo em cada rodada. Quando Fujikumo Nobutora - Devour matar um fantasma, restaure HP para você.",
  str_monster_ability_2902201 = "Um Eclipsite horrível que acumula valor de contusão ao sofrer danos durante o dia. Capaz de contra-atacar, ele inflige DANO em alvos próximos e restaura HP de acordo com seu valor de contusão toda vez que um Auroriano libera uma Habilidade Ativa. Seus poderes parecem aumentar após o anoitecer!",
  str_monster_ability_2902202 = "Acumula valor de contusão ao sofrer danos durante o dia. Capaz de contra-atacar, Helios inflige DMG em alvos próximos e restaura HP de acordo com seu valor de contusão toda vez que um Auroriano libera uma Habilidade Ativa. Ele se transforma em um Eclipsite mais poderoso após o anoitecer, perdendo temporariamente habilidades de contusão, mas é capaz de se mover 3 vezes a cada rodada.",
  str_monster_ability_2902301 = "Capaz de se mover engenhosamente no campo e resistir aos ataques normais de Aurorian, bem como à maioria dos danos ao solo usando os obstáculos. Quando o obstáculo é destruído, corre rapidamente para os obstáculos próximos. As habilidades Claudia lança obstáculos próximos serão mais poderosos do que quando são lançados no chão.",
  str_monster_ability_2902401 = "Possui forte DEF que torna Claudia quase imbatível no campo de batalha.",
  str_monster_ability_2902501 = "Minos alternará entre dois estados com base em sua pilha de Marcas. Quando ele estiver no Estado Mortal e no Estado Minotauro, ele redefinirá todas as peças pelas quais passou para peças aprimoradas e enfraquecidas, respectivamente. Quanto mais peças aprimoradas houver no tabuleiro, mais poderoso será o Minos.",
  str_monster_ability_2902601 = "É capaz de acumular Bruise ao receber dano durante o dia, convertendo-o em HP à noite enquanto se torna um Eclipsite mais poderoso, capaz de causar dano a todos os inimigos na tela.",
  str_monster_ability_2902701 = "Parece ser um oponente muito poderoso que pode derrubar o alvo a cada rodada e convocar Eclipsites para ajudar na batalha. Pode até controlar a geração da Dark Region.",
  str_monster_name_2910271 = "Coagulating Goldor",
  str_monster_ability_2910271 = "Possui ataque em tela cheia, mas também possui defesa aumentada. Depois de receber certa quantidade de dano a cada rodada, não recebe mais dano nenhum.",
  str_monster_name_2100111 = "Spellhound Warden",
  str_monster_ability_2100111 = "Um Magicanino modificado com uma barreira mais forte do que a de Magicaninos comuns, recebendo maior resistência a danos.",
  str_monster_name_2910211 = "Bloodthirsty Umbrahulk",
  str_monster_ability_2910211 = "Um Eclipsita sanguinário que recupera PV após atacar alvos. Seus ataques corpo a corpo acompanham efeito de empurrão e podem invocar Pedras. Também podem lançar um ataque em tela cheia, causando dano baseado no número de Pedras invocadas.",
  str_monster_name_2910701 = "Modified T1024",
  str_monster_ability_2910701 = "Após a modificação, o T1024 pode se restaurar ao atacar. Ataques causam efeito de empurrão no alvo; refletirá dano se for atacado durante sua defesa; possui alto poder de recuperação; invoca um T256 ao morrer.",
  str_monster_name_2910501 = "Shifting Solmorph",
  str_monster_name_2920501 = "Evolved Solmorph",
  str_monster_name_2910601 = "Shadowborn Solfall",
  str_monster_name_2910451 = "Umbral Phorosion",
  str_monster_ability_2910451 = "Esconde-se na Lumiwall mais distante do jogador. Ataques podem mudar de elemento das casas durante sua rota do ataque. Quebre 3 Lumiwalls para fazê-lo aparecer.",
  str_monster_name_2910403 = "Grievous Schummer",
  str_monster_ability_2910403 = "Hábil em ataques a distância e AdE, pode sincronizar seu PV. Sincronizar: Schummer de menor PV sincronizará seu PV com Schummer de maior PV no campo de batalha, restaurando seu PV.",
  str_monster_name_2920403 = "Shattered Schummer",
  str_monster_ability_2920403 = "Restaura PV quando é atacado por Aurorians com elementos eficientes. Hábil em ataques a distância e AdE, pode sincronizar seu PV. Sincronizar: Schummer de menor PV sincronizará seu PV com Schummer de maior PV no campo de batalha, restaurando seu PV.",
  str_monster_name_2910411 = "Rueful Gertzurde",
  str_monster_ability_2910411 = "Quando Gertzurde está no modo Fúria, os ataques normais acertarão duas vezes e ele invocará reforços. Os ataques darão debuff de ataque e defesa aos inimigos atingidos. Agora, o alcance de Gertzurde é o tabuleiro inteiro.",
  str_monster_name_2910441 = "Ferocious Herkeros",
  str_monster_name_2910611 = "Augmented Deathless",
  str_monster_ability_2910611 = "Incapaz de se mover, mas tem habilidade em ataques em forma de cruz e de longa distância; ataques causam perda de energia de Aurorians, o que aumenta o número de rodadas de recarga de Habilidades Ativas; se divide ao morrer. Cada vez que um Sem Morte morre, os Sem Morte restantes recuperam todo o PV.",
  str_monster_name_2910252 = "Berserk Phantom",
  str_monster_ability_2910252 = "Ganha certa quantidade de ATQ por rodada e depois de receber certa quantidade de dano a cada rodada, não recebe mais nenhum. Lança um ataque em forma de cruz e invoca clones para lutar ao seu lado. Após clonar, absorve o PV dos clones anteriores para restaurar seu PV. Quando seu PV está abaixo de 50%, seus ataques normais viram ataques duplos e ataques em área viram ataques em tela cheia.",
  str_monster_name_2100241 = "Ravenous Croweye",
  str_monster_ability_2100241 = "Um Eclipsita com um nível médio de habilidades de invocação. Incapaz de se mover por conta própria, luta invocando Falhas.",
  str_monster_name_2910431 = "Earthsplitting Mara Sol",
  str_monster_ability_2910431 = "É excelente em usar seu grande corpo para atacar alvos à sua frente. Ele entra no solo e causa dano a alvos próximos ao emergir, enquanto invoca Insetos Explosivos.",
  str_monster_name_2910141 = "Rabid Shelt",
  str_monster_ability_2910141 = "Habilidoso com ataques corpo a corpo, também pode lançar dois ataques normais a cada rodada. Seus ataques atordoam alvos e invocam Alma Sombria e Carniceiros. Possui habilidade de contra-ataque, invocando Alma Sombria ou Carniceiros para ajudar na batalha sempre que Aurorians usarem habilidades.",
  str_monster_name_2910182 = "Rabid Shire",
  str_monster_ability_2910182 = "Habilidoso com ataques a distância, também pode lançar dois ataques normais a cada rodada. Seus ataques empurram alvos e invoca Alma Sombria e Carniceiros. Possui habilidade de contra-ataque, invocando Alma Sombria ou Carniceiros para ajudar na batalha sempre que Aurorians usarem habilidades.",
  str_monster_name_2910231 = "Bloodthirsty Philex",
  str_monster_ability_2910231 = "Um Eclipsita sanguinário que recupera PV após atacar alvos. Seus ataques corpo a corpo causam efeito de empurrão e suas habilidades de ataque atordoam alvos.",
  str_monster_name_2910232 = "Analeptic Vani",
  str_monster_ability_2910232 = "Um Eclipsita sanguinário que recupera PV após atacar alvos. Pode usar Energia para golpear a distância e restaura PV para Filex.",
  str_monster_name_2910221 = "Boredom Splitter",
  str_monster_ability_2910221 = "Ignora dano de Aurorians com o mesmo elemento que ele mesmo e restaura PV quando é atacado por Aurorians ineficazes contra este elemento. Seus ataques normais causam efeito de empurrão. Libera uma ampla gama de ataques baseados em seu elemento. Fogo - Grande dano em área com efeitos de Incêndio, Trovão - Dano em tela cheia que aleatoriamente gera Pestespinhos.",
  str_monster_name_2100311 = "Augean Annihilator",
  str_monster_ability_2100311 = "Pode atacar seu alvo quatro vezes. Imune a dano de habilidade. Defesa de Movimento: toda vez que Aurorians usam uma Habilidade Ativa nesta rodada, o movimento Aniquilador Augeano aumenta em 2 na próxima.",
  str_monster_name_21003111 = "Augeano",
  str_monster_ability_21003111 = "Imune a dano de habilidade.",
  str_monster_ability_21003112 = "Contador de Movimento: Toda vez que Aurorianos usam uma Habilidade Ativa nesta rodada, o alcance de movimento do Aniquilador Augeu aumenta em +2 na próxima rodada.",
  str_monster_name_21003111_en = "Augean",
  str_monster_ability_21003111_en = "Immune to skill damage.",
  str_monster_name_2250281 = "Enslaved Dark Summoner",
  str_monster_name_9100161 = "Sombra Necrosante",
  str_monster_desc_9100161 = "Quando certas sombras entram na torre, o poder especial da luz que existe aqui faz com que se transformem, aumentando sua capacidade de caçar suas presas. É por esta razão que lhes é atribuída a tarefa de lidar com exploradores que se atrevam a entrar na Torre.",
  str_monster_ability_9100161 = "Usa sua lança para atacar o alvo. Possui a habilidade para invocar Atrivespa.",
  str_monster_name_5400231 = "Bloodthirsty Philex",
  str_monster_ability_5400231 = "Um Eclipsita sanguinário que recupera PV após atacar alvos. Seus ataques corpo a corpo empurram alvos e ataques de habilidades atordoam alvos.",
  str_monster_name_5400232 = "Analeptic Vani",
  str_monster_ability_5400232 = "Um Eclipsita sanguinário que recupera PV após atacar alvos. Pode usar Energia para golpear a distância e restaura PV para Filex.",
  str_monster_name_20005011 = "Rhein",
  str_monster_desc_20005011 = "Para escapar da punição de Lumópolis, ele usou seus fortificantes para se transformar de um ex-líder de guilda em um monstro maligno.",
  str_monster_ability_20005011 = "O Rhein mutante pode puxar alvos distantes para perto de si e lançar ataques e Pestespinho em alvos dentro de 1 círculo ao redor.",
  str_monster_name_20002441 = "Lachon Hermes",
  str_monster_desc_20002441 = "Através de um desejo por poder e vida longa, ele se transformou em um lacaio de Eclipse, finalmente se tornando a monstruosidade que você vê.",
  str_monster_ability_20002441 = "O Lachon mutante ganha uma habilidade de invocação avançada. Ele não pode se mover e luta invocando grupos de Eclipsitas.",
  str_monster_name_3900281 = "Invocador Escuro Perverso",
  str_monster_alias_3900281 = "Códice da Desolação",
  str_monster_desc_3900281 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900281 = "Invoca sinais em um local fixo e restaura o PV do sinal. Causa dano adicional com base no número de sinais. Sua habilidade é um ataque à distância em forma de cruz que pode ser carregada para causar dano na tela inteira.",
  str_monster_name_3900264 = "Dawn Perversa",
  str_monster_alias_3900264 = "Códice da Desolação",
  str_monster_desc_3900264 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900264 = "Causa dano aos inimigos dentro de 2 círculos ao redor e a todos os inimigos no campo de batalha. Pode gerar Fada Dawn em um local fixo e ordenar que causem dano ao inimigo.",
  str_monster_name_3900641 = "Caracalune Perverso",
  str_monster_alias_3900641 = "Códice da Desolação",
  str_monster_desc_3900641 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900641 = "Destaca-se no uso de Ataques a Distância. Após usar Ataque a Distância em Cruz,  bloqueia o elemento da casa em que está.",
  str_monster_name_3900661 = "Bomba Destruidora Perversa",
  str_monster_alias_3900661 = "Códice da Desolação",
  str_monster_desc_3900661 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900661 = "Destaca-se no uso de Ataques a Distância. Após usar Ataque a Distância em Cruz e destrói a casa em que está.",
  str_monster_name_3900211 = "Umbrahulk Perverso",
  str_monster_alias_3900211 = "Códice da Desolação",
  str_monster_desc_3900211 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900211 = "Pode Invocar Pedras e ordenar que ataquem. Os alvos atingidos são empurrados para trás e novas Pedras são geradas no local. Pode lançar ataques na tela toda. O dano causado depende do número atual de Pedras.",
  str_monster_name_3900251 = "Fantasma Perverso",
  str_monster_alias_3900251 = "Códice da Desolação",
  str_monster_desc_3900251 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900251 = "Pode lançar ataques em área na Forma de Cruz. Invoca clones para atacar a tela toda.",
  str_monster_name_3900411 = "Gertzurde Perverso",
  str_monster_alias_3900411 = "Códice da Desolação",
  str_monster_desc_3900411 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3900411 = "Invoca reforços em batalha. Cada ataque adiciona um debuff de DEF aos inimigos e o alcance do ataque se estende por todo o tabuleiro. Ataques normais acertarão duas vezes.",
  str_monster_name_3000451 = "Servo Perverso",
  str_monster_alias_3000451 = "Códice da Desolação",
  str_monster_desc_3000451 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3000451 = "Ao rugir, os ataques acumulam um debuff de DEF nos alvos atingidos.",
  str_monster_name_3000602 = "Fada Dawn Perversa",
  str_monster_alias_3000602 = "Códice da Desolação",
  str_monster_desc_3000602 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3000602 = "Comandados por Dawn para batalhar com o inimigo, eles se agarram ao corpo do inimigo quando estiverem a 1 círculo ao redor e causam dano ao seu alvo.",
  str_monster_name_3000131 = "Sinal Perverso",
  str_monster_alias_3000131 = "Códice da Desolação",
  str_monster_desc_3000131 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3000131 = "Um Sinal invocado por um Invocador Escuro. Aumenta o ATQ do Invocador Escuro.",
  str_monster_name_3910451 = "Forosão Perverso",
  str_monster_alias_3900451 = "Códice da Desolação",
  str_monster_desc_3900451 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3910451 = "Ao usar ataques à distância, cria uma ilusão em um local fixo. Ao colidir com os alvos, cria uma ilusão ao lado do alvo.",
  str_monster_name_2001501 = "Fantasma",
  str_monster_desc_2001501 = "Um monstro especial do Extremo Oriente que dizem ser \"nem vivo nem morto\" e é extremamente hostil com os vivos.",
  str_monster_ability_2001501 = "Suas habilidades de luta podem não ser assustadoras, mas seus números são.",
  str_monster_name_21601191 = "Revy",
  str_monster_name_21601191_en = "Revy",
  str_monster_name_21601171 = "Gram",
  str_monster_name_21601171_en = "Gram",
  str_monster_name_21601291 = "Luke",
  str_monster_name_21601291_en = "Luke",
  str_monster_name_21500991 = "Areia",
  str_monster_name_21500991_en = "Areia",
  str_monster_name_21500751 = "Odi",
  str_monster_name_21500751_en = "Odi",
  str_monster_name_21300531 = "Jomu",
  str_monster_name_21300531_en = "Jomu",
  str_monster_name_21400401 = "Joanie Boom",
  str_monster_name_21400401_en = "Joanie Boom",
  str_monster_desc_21601191 = "Uma nova recruta de Illumina. Genial em combate, mas indiferente, impulsiva e uma comunicadora falha. Anseia por glória em batalha e se provar capaz.",
  str_monster_desc_21601171 = "Um veterano que serviu nas linhas de defesa de Illumina, ele se aposentou e agora trabalha com logística. Por fora parece durão, mas por dentro é uma pessoa doce, ele é um aliado de confiança no campo de batalha.",
  str_monster_desc_21601291 = "O subcomandante de um esquadrão de mercenários de Umbraton, um homem de honra, sabe tudo na cidade. Ele está trabalhando para expandir as forças de mercenários.",
  str_monster_desc_21500991 = "Uma mercenária errante de Umbraton. Nasceu com uma maldição que a tornou anêmica e depende de sua espada mágica para sobreviver.",
  str_monster_desc_21500751 = "Uma integrante da Equipe Técnica da Rediesel Wrench altamente confiante em suas tecnologias de comunicação. Gosta de gritar e reclamar de todos no Canal de Comunicação, mas se afoba quando há problemas.",
  str_monster_desc_21300531 = "Um comerciante da Rediesel Wrench. Um típico mercador inescrupuloso, ele nunca deixa uma oportunidade de lucro escapar... Se confrontado com tarefas difíceis, sua faca curta normalmente dá conta do serviço.",
  str_monster_desc_21400401 = "Uma garotinha fascinada por explosões que sente uma empolgação fora do comum quando algo vai pelos ares. Tal obsessão rendeu a ela um lugar na Rediesel Wrench. Ela passa seus dias estudando explosivos, e não dá a mínima se sua vida corre algum perigo...",
  str_monster_ability_21601191 = "Adepto de ataques à distância, causa dano a uma área de coluna.",
  str_monster_ability_21601171 = "Adepto de ataques corpo a corpo, ele usa suas habilidades para causar grandes danos em área aos inimigos ao redor.",
  str_monster_ability_21601291 = "Adepto de ataques à distância, ele usa sua habilidade de tela cheia para causar dano e infligir Marca Parasitária nos inimigos. Cada vez que o inimigo se move, ele recebe dano de Marca Parasitária.",
  str_monster_ability_21500991 = "Adepto de ataques de área, suas habilidades aumentam seu próprio ACT e ATK para causar grandes danos em área.",
  str_monster_ability_21500751 = "Adepto de ataques à distância, seus ataques infligem Veneno.",
  str_monster_ability_21300531 = "Adepto de ataques corpo a corpo, seus ataques infligem Sangramento.",
  str_monster_ability_21400401 = "Ela não se move, mas usa uma grande área de ataque, muda os elementos do bloco dentro do alcance e inflige Burn.",
  str_monster_name_1300221 = "Chainsaw Rick",
  str_monster_desc_1300221 = "Um garoto barulhento e bagunceiro que nunca sossega e sempre usa um chapéu de coelho. Ele está sempre forçando seus limites em batalha, algo frequentemente confundido com uma tendência suicida. É um milagre ele ainda estar vivo.",
  str_monster_ability_1300221 = "Motosserra Rick causa dano à unidade inimiga mais próxima ao redor de um ladrilho vermelho.",
  str_monster_name_1300521 = "Dove",
  str_monster_desc_1300521 = "Uma carteira que trabalha para a Federação Illumina, apesar de não integrá-la de fato. Ela fornece apenas serviços postais, e é uma preguiçosa sem nenhum orgulho profissional que faria qualquer coisa para faltar ao trabalho.",
  str_monster_ability_1300521 = "Pomba causa dano à unidade inimiga mais próxima ao redor de um quadrado verde.",
  str_monster_name_1400321 = "Angel",
  str_monster_desc_1400321 = "Uma Integrante da Equipe da Corte de Justiça Lumo e um anjo de uma asa só. Ela é sensível e orgulhosa. Apesar de sua idade, Angel ja vivenciou a guerra..",
  str_monster_ability_1400321 = "Anjo causa dano à unidade inimiga mais próxima ao redor de um ladrilho amarelo.",
  str_monster_name_1501491 = "Roy",
  str_monster_desc_1501491 = "O gerente de logística da Rediesel Wrench. Embora ele pareça desorganizado, ele é de fato muito atencioso e protetor com todos em Rediesel Wrench.",
  str_monster_ability_1501491 = "Roy causa dano à unidade inimiga mais próxima ao redor de um ladrilho amarelo.",
  str_monster_name_1400411 = "Srta. Blanc",
  str_monster_desc_1400411 = "Uma mulher serena e elegante que atua como guia para os recém-chegados a Lumópolis. Mantém-se calma mesmo durante uma catástrofe, o que indica um passado extraordinário. Mas quando questionada a respeito, ela apenas sorri misteriosamente...",
  str_monster_ability_1400411 = "A Sra. Blanc não apenas causa dano à unidade inimiga mais próxima ao redor de uma peça azul, mas também transforma todas as peças ao redor dela em azul.",
  str_monster_name_1300471 = "Zoya",
  str_monster_desc_1300471 = "Uma pesquisadora genial da Federação Illumina, cuja sede por conhecimento consome toda a sua atenção... Isso, e um certo Comandante da Legião. Ainda que pareça calma, é arriscado abordá-la de forma imprudente. Para o bem de todos, é melhor não perturbá-la com frequência.",
  str_monster_ability_1300471 = "Zoya restaura HP para o companheiro de equipe com o HP mais baixo.",
  str_monster_name_1300531 = "Jomu",
  str_monster_desc_1300531 = "Um comerciante da Rediesel Wrench. Um típico mercador inescrupuloso, ele nunca deixa uma oportunidade de lucro escapar... Se confrontado com tarefas difíceis, sua faca curta normalmente dá conta do serviço.",
  str_monster_ability_1300531 = "Jomu causa dano a inimigos dentro de 1 aglomerado ao redor.",
  str_monster_name_1201631 = "Tourdog",
  str_monster_desc_1201631 = "Uma criatura fascinante do norte que é apaixonada por jogos. Sempre que se depara com alguém novo, ele sempre pergunta: \"Estimado mestre, você aceita encomendas?\"",
  str_monster_ability_1201631 = "Tem uma paixão ardente pela dança.",
  str_monster_name_1600061 = "Carleen",
  str_monster_desc_1600061 = "A Capitã dos Jardins Lumo e filha de Schwartz. Uma nobre que não tolera vilania, respeita a ordem e despreza o mal. Ainda mais impressionante é o fato dela ter se tornado uma cavaleira por mérito próprio, e não graças à influência do seu pai.",
  str_monster_ability_1600061 = "Carleen não apenas causa dano à unidade inimiga mais próxima ao redor de uma telha azul, mas também inflige dano a outros inimigos na mesma coluna e os repele.",
  str_monster_name_1600111 = "Sharona",
  str_monster_desc_1600111 = "Uma Comandante da Legião da Federação Illumina com uma beleza fria e o poder dos dragões. Apesar de seu jeito frio, ela é alguém em quem você pode confiar. Sua origem é misteriosa. Depois de se juntar à Federação, ela se tornou Comandante da Legião graças aos seus feitos militares. Sempre carrega sua lâmina Chama Azure, símbolo de sua herança.",
  str_monster_ability_1600111 = "Sharona causa dano a inimigos dentro de 2 aglomerados ao redor.",
  str_monster_name_1500331 = "Vice",
  str_monster_desc_1500331 = "Uma integrante da Federação Illumina com uma personalidade gentil. Ela não é apenas talentosa, esforçada e otimista, mas também foi treinada intensamente desde pequena graças ao reconhecimento dos seus superiores. Agora nomeada Capitã da Expedição, ela é responsável por procurar e escavar ruínas antigas.",
  str_monster_ability_1500331 = "Vício não apenas causa dano à unidade inimiga mais próxima ao redor de uma telha azul, mas também inflige dano contínuo ao inimigo mais próximo.",
  str_monster_name_1600021 = "Hiiro",
  str_monster_desc_1600021 = "Uma garota com habilidades de luta incomparáveis. Como Comandante da Legião da Federação Illumina, ela é conhecida por ser firme, rígida e determinada. Encara cada batalha com uma confiança friamente calculada, vencendo diversas batalhas com sua katana.",
  str_monster_ability_1600021 = "Hiiro não apenas causa dano à unidade inimiga mais próxima ao redor de uma telha verde, mas também inflige Crimson Sakura no inimigo mais próximo.",
  str_monster_name_2800601 = "Boi 8",
  str_monster_desc_2800601 = "Projetado especialmente para o rally, este veículo foi remodelado para atravessar terrenos acidentados. Não é apenas durável, mas também fortemente armado",
  str_monster_ability_2800601 = "Incapaz de lançar habilidades sem um driver.",
  str_monster_name_2000191 = "Totó",
  str_monster_desc_2000191 = "Na realidade, todo pequeno Slasher tem um sonho. É só que ninguém nunca se importou em perguntar.",
  str_monster_name_1500901 = "Barbara",
  str_monster_desc_1500901 = "A famosa cantora da Rediesel Wrench. Barbara aparenta ser gentil e agradável, mas revela um lado irritadiço quando encontra um fã desagradável. Ela viaja por toda parte buscando ser o ídolo mais popular.",
  str_monster_ability_1500901 = "Barbara causa dano a todos os inimigos ocupando ladrilhos vermelhos.",
  str_monster_name_1501141 = "Genevieve",
  str_monster_desc_1501141 = "Elegante caçadora de recompensas da True Order, é alegre e gosta de saborear uma bebida de vez em quando. Atualmente, ela está tentando criar uma rede de inteligência para rastrear o paradeiro de um indivíduo.",
  str_monster_ability_1501141 = "Genevieve pula nos inimigos localizados na diagonal de sua posição e, após aterrissar, causa dano a 1 aglomerado ao redor. Se houver um alvo no ponto de aterrissagem, ela causa dano severo ao alvo e o repele.",
  str_monster_name_1600141 = "Schwartz",
  str_monster_desc_1600141 = "O atual Governador de Lumópolis, cuja posição e status o colocam muito acima das outras pessoas. Mas tal sucesso tem seu preço, e a solidão é sua eterna companheira. Ainda assim, Schwartz passa incontáveis horas mantendo a ordem em Lumópolis e sempre tenta dar o melhor de si sem baixar a guarda.",
  str_monster_ability_1600141 = "Schwartz causa dano a todos os inimigos no campo de batalha enquanto convoca Lumo Guards para eliminar seus inimigos.",
  str_monster_name_2001701 = "Carreteiro",
  str_monster_desc_2001701 = "Um Eclipsite que é ativo principalmente à noite. Durante o dia, ele se prostra no chão e não consegue se mover.",
  str_monster_ability_2001701 = "Durante o dia, ele se prostra no chão e fica em posição defensiva. Uma vez que a noite começa, ela retoma seu verdadeiro estado.",
  str_monster_name_3902501 = "Minos",
  str_monster_name_3902501_en = "Minos",
  str_monster_alias_3902501 = "Códice da Desolação",
  str_monster_desc_3902501 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3902501 = "Evoca uma peça enfraquecida em uma posição aleatória a cada rodada. Causa dano ao alvo uma vez cada vez que passa por uma peça enfraquecida. A habilidade carregável causa dano em tela cheia.",
  str_monster_name_3903101 = "Barbara",
  str_monster_name_3903101_en = "Barbara",
  str_monster_alias_3903101 = "Códice da Desolação",
  str_monster_desc_3903101 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3903101 = "Sempre mova para o local mais distante do alvo. Causa dano em área grande, exceto em algumas zonas seguras específicas. A habilidade carregável causa dano em tela cheia e repele os alvos.",
  str_monster_name_3903201 = "Connolly",
  str_monster_name_3903201_en = "Connolly",
  str_monster_name_3903301 = "Beryl",
  str_monster_name_3903301_en = "Beryl",
  str_monster_alias_3903201 = "Códice da Desolação",
  str_monster_alias_3903301 = "Códice da Desolação",
  str_monster_desc_3903201 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_desc_3903301 = "1. Monstros perversos se aprimoram continuamente de acordo com a quantidade de dano que recebem. Cada acúmulo de aprimoramento aumenta o ATQ deles em 10%.\n2. O ATQ de monstros aumenta em 8% e a DEF em 5% a cada rodada.",
  str_monster_ability_3903201 = "Tentáculos são invocados a cada rodada em pontos aleatórios para impedir o movimento dos Aurorianos. O HP dos tentáculos aumenta rodada a rodada. Habilidades causam dano em área e habilidades carregáveis causam dano em tela cheia.",
  str_monster_ability_3903301 = "Cristal Sanguíneo é invocado a cada rodada em pontos aleatórios para impedir o movimento dos Aurorianos. Quando Nefarious Beryl passa por um cristal, ela quebra o cristal e ganha um aumento de ATK com ele. Habilidades causam dano em área e habilidades carregáveis causam dano em tela cheia.",
  str_monster_name_3903401 = "Schwartz",
  str_monster_name_3903401_en = "Schwartz",
  str_monster_ability_2900913 = "Ataca onde quer que o jogador esteja localizado na rodada anterior. Este monstro ressuscitará em seu local várias rodadas após morrer.",
  str_monster_name_2903001 = "Guardião do Núcleo",
  str_monster_name_2903001_en = "Core Guardian",
  str_monster_desc_2903001 = "Um guardião gigantesco que protege o núcleo de energia da nave. Ele vai acordar e lutar quando o Núcleo estiver sob ameaça.",
  str_monster_ability_2903001 = "Esse ser poderoso tem a capacidade de alterar todo o tabuleiro, mas também possui um calcanhar de Aquiles.",
  str_monster_name_2001801 = "Roda do Britador",
  str_monster_desc_2001801 = "Um dos sistemas de defesa do Núcleo de Energia e difícil de destruir. Ele lançará ataques sem fim aos inimigos.",
  str_monster_ability_2001801 = "Um ser indestrutível. Quando seu HP estiver em zero, ele entrará em um estado paralisado. Torna-se invencível nesse estado e recupera HP automaticamente a cada rodada. Quando seu HP estiver cheio, ele recuperará a capacidade de se mover e agir.",
  str_monster_name_2001802 = "Módulo de congelamento",
  str_monster_desc_2001802 = "O módulo de resfriamento permite que o poderoso Core Guardian funcione normalmente.\nPode ser a única fraqueza do guardião, mas se você se aproximar dele precipitadamente, vai se queimar com o calor que ele emite.",
  str_monster_ability_2001802 = "Interrompe uma área e causa dano aos Aurorianos para cada peça movida dentro da área afetada.",
  str_monster_desc_2900311 = "Incrivelmente poderoso Eclipsite, que dizem ter lutado em inúmeras guerras. Um ser forte que sobreviveu a chuvas de balas e bombas. Ninguém sabe quantos de seus inimigos caíram sob suas lâminas.",
  str_monster_passiveskill_name_2900144 = "Out of the Blue: Gloom Ghoul",
  str_monster_passiveskill_desc_2900144 = "Evoca uma Runa em um local aleatório, que se transforma em um Gloom Ghoul em 3 rodadas.",
  str_monster_passiveskill_name_2900184 = "Do nada: Shadowgeist",
  str_monster_passiveskill_desc_2900184 = "Evoca uma Runa em um local aleatório, que se transforma em Shadowgeist em 3 rodadas.",
  str_monster_passiveskill_name_2000451 = "Sacrifício do Servo",
  str_monster_passiveskill_desc_2000451 = "Restaura uma certa quantidade de HP para o jogador quando morto.",
  str_monster_passiveskill_name_2900611 = "Imortal: Clone",
  str_monster_passiveskill_desc_2900611 = "Divide-se em unidades de combate menores quando morto.",
  str_monster_passiveskill_name_2900641 = "Caracalune: Contaminação",
  str_monster_passiveskill_desc_2900641 = "Causa uma pequena quantidade de dano ao jogador e bloqueia as peças dentro de 1 aglomerado ao redor do jogador.",
  str_monster_passiveskill_name_2900661 = "Shatterblast: Fenda da Terra",
  str_monster_passiveskill_desc_2900661 = "Gera 2 ladrilhos danificados aleatoriamente no campo.",
  str_monster_passiveskill_name_2900671 = "Schummer: Aniquilação",
  str_monster_passiveskill_desc_2900671 = "Quando todos os Daemons de Schummer forem ativados, Schummer lança uma habilidade que derrota tudo na tela.",
  str_monster_passiveskill_name_2902200 = "Contra-ataque noturno",
  str_monster_passiveskill_desc_2902200 = "Causa dano a alvos dentro de 2 aglomerados ao redor e recupera um pouco de HP com base na Contusão acumulada.",
  str_monster_passiveskill_name_2902301 = "Claudia: Plataforma",
  str_monster_passiveskill_desc_2902301 = "Claudia não pode ser danificada por ataques normais quando estiver em uma plataforma ou Asher.",
  str_monster_passiveskill_name1_2902301 = "Claudia: Teletransporte",
  str_monster_passiveskill_desc1_2902301 = "Quando a plataforma sob ela é quebrada, ou Asher é nocauteado, Claudia se teletransporta para outra plataforma dentro de 2 aglomerados ao redor ou cai no chão.",
  str_monster_passiveskill_name_9000101 = "Voar",
  str_monster_passiveskill_desc_9000101 = "Este inimigo pode atravessar o abismo.",
  str_monster_passiveskill_name_2000311 = "Corte Duplo",
  str_monster_passiveskill_desc_2000311 = "Dreadblades ataca o alvo duas vezes.",
  str_monster_passiveskill_name_2000221 = "Pestespinho",
  str_monster_passiveskill_desc_2000221 = "Gera Spikepest em ladrilhos que foram pisados.",
  str_monster_passiveskill_name_2000511 = "Confusão",
  str_monster_passiveskill_desc_2000511 = "Ao acertar um alvo, aumenta as rodadas de recarga da habilidade ativa deste auroriano.",
  str_monster_passiveskill_name_2000521 = "Confinamento Lúmina",
  str_monster_passiveskill_desc_2000521 = "Bloqueia as peças em 1 cluster ao redor após mover. Perde o efeito quando atordoado, amedrontado, paralisado ou infligido com outros efeitos de controle.",
  str_monster_passiveskill_name_2000551 = "Rancor",
  str_monster_passiveskill_desc_2000551 = "Ao atacar, aplica uma maldição em Aurorians do mesmo elemento. Aurorians amaldiçoados não serão capazes de atacar ou usar Habilidades Ativas.",
  str_monster_passiveskill_name1_2000551 = "Dissipação de rancor",
  str_monster_passiveskill_desc1_2000551 = "Quando morto, remove maldições colocadas por Cursed Fay em Aurorianos do mesmo elemento.",
  str_monster_passiveskill_name_2001701 = "Parada de carreteiros",
  str_monster_passiveskill_desc_2001701 = "Fica prostrado no chão em posição defensiva durante o dia. Assim que a noite começa, ela retoma seu verdadeiro estado e ataca os Aurorianos.",
  str_monster_passiveskill_name_2901001 = "Homem no Quadro",
  str_monster_passiveskill_desc_2901001 = "Esconde-se quando em peças danificadas, recebendo apenas dano de área e se torna imune a ataques e habilidades normais onde uma peça é selecionada.",
  str_monster_passiveskill_name_2901301 = "Aurora enfraquecida",
  str_monster_passiveskill_desc_2901301 = "O dano recebido durante a Hora da Aurora aumenta muito.",
  str_monster_passiveskill_name_2001301 = "Aurora Vital",
  str_monster_passiveskill_desc_2001301 = "Só pode ser atacado por Aurorianos durante o Tempo de Aurora.",
  str_monster_passiveskill_name_2903001 = "Núcleo Guardião Intacto",
  str_monster_passiveskill_desc_2903001 = "Quando o Core Guardian está alerta, só recebe dano de alvo único de ataques que não selecionam peças e se torna imune a ataques normais e de área.",
  str_monster_passiveskill_name1_2903001 = "Núcleo Guardião Paralisado",
  str_monster_passiveskill_desc1_2903001 = "Mais pontos fracos são expostos depois que o Core Guardian é paralisado e a imunidade a danos é perdida.",
  str_monster_passiveskill_name_2000901 = "Autodestruição cronometrada",
  str_monster_passiveskill_desc_2000901 = "Se autodestrói após a contagem regressiva chegar a zero, destruindo a telha sob ela.",
  str_monster_passiveskill_name_2001801 = "Roda do britador paralisada",
  str_monster_passiveskill_desc_2001801 = "Quando o HP do Crusher Wheel é reduzido a zero, ele entra em um estado paralisado. Quando seu HP está cheio novamente, ele recupera a capacidade de se mover e agir.",
  str_monster_passiveskill_name_2001802 = "Falha no módulo de congelamento",
  str_monster_passiveskill_desc_2001802 = "A fraqueza do Guardião do Núcleo. Quando o HP do Freeze Module é reduzido a zero, o Core Guardian entra em um estado paralisado.",
  str_monster_passiveskill_name_2900301 = "Escudo de Boliche",
  str_monster_passiveskill_desc_2900301 = "O Escudo de Energia protege Bowlinger de receber dano. (Paralise-o atacando uma área não blindada com o Deathrider para causar dano ao Bowlinger efetivamente)",
  str_monster_passiveskill_name_2910281 = "Escudo da fonte de alimentação",
  str_monster_passiveskill_desc_2910281 = "Cada Dark Summoner Beacon no campo reduz o dano recebido pelo Dark Summoner.",
  str_monster_passiveskill_name_2010481 = "Lumiwall",
  str_monster_passiveskill_desc_2010481 = "Aurorianos só podem causar dano ao Lumiwall depois que o Phorosion estiver escondido neste Lumiwall. Outros Lumiwalls não podem ser atacados.",
  str_monster_passiveskill_name_2901201 = "Luz do Farsante",
  str_monster_passiveskill_desc_2901201 = "Claymore tem a capacidade de conectar e se mover ao longo de ladrilhos da mesma cor.",
  str_monster_passiveskill_name1_2901201 = "Tumba do Imortal",
  str_monster_passiveskill_desc1_2901201 = "Depois que Call of the Grave se dissipa, Claymore ganha uma habilidade de contador que causa dano aos Aurorianos com base no ATK do Auroriano que conjurou a habilidade e recupera seu próprio HP.",
  str_monster_passiveskill_name_2900312 = "Corte Duplo",
  str_monster_passiveskill_desc_2900312 = "Augean ataca o alvo duas vezes.",
  str_monster_passiveskill_name1_2900312 = "Toca",
  str_monster_passiveskill_desc1_2900312 = "Aumenta a distância de movimento em 2 quadrados e recupera na próxima rodada.",
  str_monster_passiveskill_name_3900451 = "Força Nefasta",
  str_monster_passiveskill_desc_3900451 = "Quando monstros Nefarious recebem dano, o efeito do contador de elemento aumenta em 100%.\nMonstros nefastos se aprimorarão continuamente de acordo com o dano que recebem. Cada pilha de aprimoramento aumenta seu ATK em 10%.\nO ATK de monstros nefastos aumenta em 8% e a DEF aumenta em 5% a cada rodada.",
  str_monster_passiveskill_name_3910281 = "Ímã de Energia",
  str_monster_passiveskill_desc_3910281 = "Cada Dark Summoner Beacon no campo aumenta o ATK do Dark Summoner.",
  str_monster_passiveskill_name_3903101 = "Escudo Nefasto",
  str_monster_passiveskill_desc_3903101 = "Imune a danos durante sua fase de ação.",
  str_monster_passiveskill_name_3903301 = "Nefarious: Crystal Summon",
  str_monster_passiveskill_desc_3903301 = "Gera Cristais Sanguíneos em locais aleatórios no campo a cada rodada (há uma restrição de número máximo).",
  str_monster_passiveskill_name_3903201 = "Nefarious: Nascido do Medo",
  str_monster_passiveskill_desc_3903201 = "Gera tentáculos em locais aleatórios no campo a cada rodada (há uma restrição de número máximo).",
  str_monster_passiveskill_name_3902501 = "Nefarious: Enfraquecimento designado",
  str_monster_passiveskill_desc_3902501 = "Gera ladrilhos enfraquecidos em locais aleatórios no campo a cada rodada.",
  str_monster_passiveskill_name_2901341 = "Coração Despedaçado",
  str_monster_passiveskill_desc_2901341 = "Reduz a DEF do Fearmonger sempre que um lacaio do Fearmonger morre.",
  str_monster_passiveskill_name_29009211 = "Armadura Recolhida",
  str_monster_passiveskill_desc_29009211 = "A DEF inicial de Hylingerr é muito alta, o que diminui à medida que a Sanidade do Aurorian diminui, até um mínimo de 40%.",
  str_monster_passiveskill_name_2912101 = "Devorador de Fantasmas",
  str_monster_passiveskill_desc_2912101 = "Restaura 1% do HP máximo ao receber um fantasma.\nReduz a própria DEF em 1% quando um fantasma no campo morre.",
  str_monster_name_2903901 = "Casta",
  str_monster_name_2903901_en = "Casta",
  str_monster_desc_2903901 = "Aparentemente distante, mas na verdade muito responsável. Juntou-se a Pollux para formar a dupla de mercenários apelidada de \"Raven's Blood\" para melhor defender as crianças que vivem na igreja.",
  str_monster_ability_2903901 = "Ataca inimigos à distância com uma baioneta ou ataca-os à distância com balas. Ataca inimigos com habilidades diferentes de acordo com sua localização.",
  str_monster_passiveskill_name_29039011 = "Roleta Russa: Contador",
  str_monster_passiveskill_desc_29039011 = "Sempre que um auroriano usa uma habilidade ativa, Casta move 2 peças em direção ao auroriano. Quando há algum Auroriano dentro de 1 aglomerado ao redor de Casta, ela lança a habilidade para atacar o Auroriano.",
  str_monster_passiveskill_desc_29039012 = "Sempre que um auroriano usa uma habilidade ativa, Casta move 3 peças em direção ao auroriano. Quando há algum Auroriano dentro de 1 aglomerado ao redor de Casta, ela lança a habilidade para atacar o Auroriano.",
  str_monster_passiveskill_desc_29039013 = "Sempre que um auroriano usa uma habilidade ativa, Casta move 3 peças em direção ao auroriano e aplica 2 camadas de escudo de contagem a si mesma. Quando há algum Auroriano dentro de 1 aglomerado ao redor de Casta, ela lança a habilidade para atacar o Auroriano.",
  str_monster_name_2903701 = "Canhão Autopropulsado",
  str_monster_name_2903701_en = "Self-Propelled Cannon",
  str_monster_desc_2903701 = "Guardas poderosos capazes de patrulhar por conta própria. Ambos os canhões principais e de ombro são incrivelmente poderosos. Apenas um desses guardas pode causar grandes danos.",
  str_monster_ability_2903701 = "Ele pode usar torres para causar dano contínuo ao inimigo e afastar quaisquer inimigos que cheguem muito perto dele. O guarda se fortalecerá quando perceber uma grande ameaça.",
  str_monster_ability_4000445 = "Lança ataques corpo a corpo contra alvos, e converte todas as peças ao longo de seu caminho de movimento em peças de seu próprio elemento, gerando pragas de espinhos ao longo do caminho.",
  str_monster_passiveskill_name_4000445 = "Chama de Murkmite",
  str_monster_passiveskill_desc_4000445 = "Gera pragas ao longo de seu caminho de movimento e converte peças passadas em vermelhas.",
  str_monster_name_21500781 = "Robyn",
  str_monster_name_21500781_en = "Robyn",
  str_monster_desc_21500781 = "Integrante dos Pardais de Umbraton. Tímida e introvertida, ela fica sempre por perto de sua irmã, Dayna, enquanto tenta sobreviver em Umbraton.",
  str_monster_ability_21500781 = "Dayna se torna mais poderosa quando derrotada.",
  str_monster_name_21400481 = "Dayna",
  str_monster_name_21400481_en = "Dayna",
  str_monster_desc_21400481 = "Apesar de sua pouca idade, ela já é a líder dos Pardais. Conhecida por estabelecer uma forte presença nos becos sujos e sombrios de Umbraton com sua determinação incomparável e armas diabólicas.",
  str_monster_ability_21400481 = "Adepto de ataques à distância, causa dano a uma área de coluna.",
  str_monster_name_21400911 = "Chloe",
  str_monster_name_21400911_en = "Chloe",
  str_monster_desc_21400911 = "Uma musicista gentil e amigável de Lumópolis que se perde facilmente em suas lembranças tristes. Sua família morreu na guerra, e por isso ela tem dificuldades em esquecer seu sofrimento.",
  str_monster_ability_21400911 = "Aumenta o ATK do aliado com base no número de peças azuis no campo.",
  str_monster_ability_21400912 = "Aumenta o ATK do aliado com base no número de peças azuis no campo. Também aumenta ACT.",
  str_monster_name_21200501 = "Korgon",
  str_monster_name_21200501_en = "Korgon",
  str_monster_desc_21200501 = "Um tubarão assustador, mesmo quando sorri! Ele é o protetor de um pequeno assentamento, e apesar da sua aparência feroz e temível, é um gentil amante de gatos.",
  str_monster_ability_21200501 = "Causa ataques poderosos que podem causar knockback ao atingir um alvo.",
  str_monster_name_21300491 = "Seleucid",
  str_monster_name_21300491_en = "Seleucid",
  str_monster_desc_21300491 = "Um guerreiro alto e forte que costuma caminhar por Umbraton usando sua armadura completa e seu espadão. Um homem de poucas palavras, ele nunca tira o capacete e prefere força bruta a diálogos.",
  str_monster_ability_21300491 = "Redefine ladrilhos não azuis dentro de 1 aglomerado ao redor enquanto causa dano.",
  str_monster_ability_4900251 = "Lida com ataques de área em forma de cruz e convoca um clone para lutar ao lado. Ao se clonar, ele absorve o HP do clone anterior para recuperar HP e aumentar seu ATK. Quando o clone está presente, a forma real do Phantom também pode evitar ataques, mas também sofrerá dano quando o clone for ferido.",
  str_monster_ability_4910252 = "Ao chegar, torna-se raivoso e convoca um clone para lutar ao lado. Se o Phantom absorver o clone, ele recupera HP e aumenta muito o ATK.",
  str_monster_passiveskill_name_290370113 = "Reação do Mecanismo",
  str_monster_passiveskill_desc_290370113 = "Move 1 ladrilho e invoca 1 T256 na frente",
  str_monster_name_4910181 = "Regina",
  str_monster_name_4910181_en = "Regina",
  str_monster_desc_4910181 = "Sua natureza intrépida e desinibida, assim como sua impulsividade, são as marcas de uma verdadeira alma roqueira! Seu feroz estilo musical a tornou muito popular na Rediesel Wrench, permitindo a ela não apenas inspirar as tropas, mas também liderá-las na batalha.",
  str_monster_ability_4910181 = "Persegue inimigos e lança ataques com ação intimidadora.",
  str_monster_name_4903101 = "Barbara",
  str_monster_name_4903101_en = "Barbara",
  str_monster_desc_4903101 = "A famosa cantora da Rediesel Wrench. Barbara aparenta ser gentil e agradável, mas revela um lado irritadiço quando encontra um fã desagradável. Ela viaja por toda parte buscando ser o ídolo mais popular.",
  str_monster_ability_4903101 = "Joga \"bombas\" no campo para atrapalhar os inimigos.",
  str_monster_ability_49031011 = "Convoca itens para o campo para atrapalhar os inimigos.",
  str_monster_name_4910301 = "Sinsa",
  str_monster_name_4910301_en = "Sinsa",
  str_monster_desc_4910301 = "O resoluto líder da Rediesel Wrench. É extremamente próximo de seus companheiros e o maior protetor de sua irmãzinha. Seu principal objetivo é garantir a sobrevivência da gangue.",
  str_monster_ability_4910301 = "Um poderoso atacante cuja força se transforma após a derrota de Eve.",
  str_monster_name_4911051 = "Eve",
  str_monster_name_4911051_en = "Eve",
  str_monster_desc_4911051 = "A irmã mais nova de Sinsa. Quando criança caiu sob a influência dos Eclipisitas e perdeu o controle. Ela recuperou sua inocência após curada.",
  str_monster_ability_4911051 = "Capaz de ataques de precisão e dano de área ampla.",
  str_monster_ability_4900141 = "Excelente em ataques corpo a corpo e tem a capacidade de convocar outros Eclipsites. Depois que ele se torna Rabid, seus ataques normais causam dano duas vezes com alcance de habilidade bastante aprimorado.",
  str_monster_ability_4900181 = "Excelente em ataques à distância que atordoam o alvo e invocam Eclipsites. Depois que ele se torna Rabid, seus ataques normais causam dano duas vezes com alcance de habilidade bastante aprimorado.",
  str_monster_passiveskill_name_21500781 = "Vínculo entre irmãos",
  str_monster_passiveskill_desc_21500781 = "Robyn se torna mais poderosa quando Dayna é derrotada.",
  str_monster_ability_4900641 = "Excelente no uso de ataques de grande área. Trava os elementos dos ladrilhos ao seu redor depois que ele se move.",
  str_monster_ability_4900661 = "Shatterblast irá esmagar telhas no início da batalha. Este ataque pode repelir alvos.",
  str_monster_name_2903801 = "Astor",
  str_monster_name_2903801_en = "Astor",
  str_monster_desc_2903801 = "Um espírito feminino errante, sem mestre nem vontade própria; além de sua aparência feminina, tudo o que resta é uma terrível inimizade para com os vivos. Através de rituais sinistros, esse espírito pode ser combinado com Darkflow para criar uma poderosa entidade sobrenatural.",
  str_monster_ability_2903801 = "Atravessa uma área designada e absorve a energia das Velas da Morte para se fortalecer.",
  str_monster_ability_39038011 = "Furiosas através de uma área designada, evocando a energia das Velas da Morte para causar dano.",
  str_monster_passiveskill_name_2903801 = "Desejo à luz de velas",
  str_monster_passiveskill_desc_2903801 = "Quando nenhum Auroriano está dentro do alcance de ataque, Astor começa a acender Deathly Candles nas proximidades (se todas as Deathly Candles estiverem acesas, Astor recupera 20% de seu HP máximo).\nAlém disso, cada Vela Mortal acesa dá a Astor 10% de redução de dano.",
  str_monster_passiveskill_name_39038011 = "Desejo à luz de velas",
  str_monster_passiveskill_desc_39038011 = "Quando nenhum auroriano estiver dentro do alcance de ataque, Astor começa a acender Velas da Morte no campo de batalha.\nSe todas as Velas da Morte estiverem acesas, Astor causa dano pesado aos aurorianos.",
  str_monster_passiveskill_name_39038012 = "Desejo à luz de velas",
  str_monster_passiveskill_desc_39038012 = "Quando nenhum auroriano estiver dentro do alcance de ataque, Astor começa a acender Velas da Morte no campo de batalha.\nSe todas as Velas da Morte estiverem acesas, Astor causa dano pesado aos aurorianos.\nSe nem todas as Velas da Morte estiverem acesas, Astor causa uma pequena quantidade de dano aos aurorianos.",
  str_monster_passiveskill_name_2903802 = "Desejo à luz de velas",
  str_monster_passiveskill_desc_2903802 = "Quando nenhum Auroriano está dentro do alcance de ataque, Astor começa a acender Deathly Candles nas proximidades (se todas as Deathly Candles estiverem acesas, Astor recupera 20% de seu HP máximo).\nAlém disso, cada Vela Mortal acesa aumenta a redução de dano de Astor, e cada Vela Mortal apagada aumenta o ATK de Astor.",
  str_monster_name_2903600 = "flor diavola",
  str_monster_name_2903601 = "diavola",
  str_monster_name_2903601_en = "Diavola",
  str_monster_desc_2903601 = "Diavola gosta de se esconder e eliminar seus inimigos furtivamente com veneno.",
  str_monster_ability_2903601 = "Diavola não pode se mover. Possui forte resistência, seu corpo envolto em espinhos venenosos. Suas flores podem atrair Dawn Sprites, mas também expõem sua fraqueza.",
  str_monster_desc_2000609 = "Uma ilusão criada por Diavola que contém um poder mágico.",
  str_monster_ability_2000609 = "Anexa-se a Diavola e aumenta seu ATK quando dentro de 1 cluster circundante de Diavola.",
  str_monster_passiveskill_name_2903600 = "Prevenção de Danos",
  str_monster_passiveskill_desc_2903600 = "As flores de Diavola só podem ser danificadas pelas habilidades do Sniper e são imunes a ataques normais e danos em área. Quando suas flores têm zero de HP restante, Diavola fica paralisada e não inflige mais Toxina aos aurorianos.",
  str_monster_passiveskill_name_2903601 = "Corrosão",
  str_monster_passiveskill_desc_2903601 = "Quando desperta, Diavola contra-ataca todos os ataques normais, infligindo 1 acúmulo de Toxina nos Aurorianos.",
  str_monster_passiveskill_name_2000609 = "Curar",
  str_monster_passiveskill_desc_2000609 = "Quando Dawn Sprite é derrotado, ele restaura uma pequena quantidade de HP da equipe e reduz o número de pilhas de toxinas da equipe.",
  str_monster_passiveskill_desc_2000639 = "Restaure um mínimo de HP para Dawn Sprite depois que ele for derrotado por Aurorians.",
  str_monster_name_2001901 = "espírito da lanterna",
  str_monster_name_2001901_en = "Lantern Spirit",
  str_monster_desc_2001901 = "Um Eclipsite que foi modificado por Asmodeus. Seus desejos são controlados por Asmodeus, então ele obedece a todos os seus comandos.",
  str_monster_ability_2001901 = "Os ataques criam cadeias que fazem com que tanto o dano recebido quanto o HP recuperado entre as partes vinculadas sejam compartilhados.",
  str_monster_passiveskill_name_2001901 = "Correntes",
  str_monster_passiveskill_desc_2001901 = "Quando uma das partes conectadas pela cadeia sofre dano ou recupera HP, a outra parte receberá a mesma quantidade de dano ou recuperará a mesma quantidade de HP. Quando a corrente é conectada a um auroriano, ela se quebra após ultrapassar um certo comprimento.",
  str_monster_passiveskill_name_2001902 = "Teletransporte",
  str_monster_passiveskill_desc_2001902 = "O Lantern Spirit pode se teletransportar se puder passar pelo ladrilho em que o auroriano está e se mover para o ladrilho do outro lado.",
  str_monster_name_2903401 = "Asmodeus",
  str_monster_name_2903401_en = "Asmodeus",
  str_monster_desc_2903401 = "O poderoso Wraith tem a habilidade terrível de ver através de todos os desejos de seus oponentes e gosta de manipulá-los.",
  str_monster_ability_2903401 = "Quando o Asmodeus imune a dano de ataque normal e o Asmodeus imune a dano de habilidade estão ambos no campo, seu HP é compartilhado através da Chain of Desire, e ela também pode torturar sua presa com sua Chain of Nightmares.",
  str_monster_passiveskill_name_29034001 = "Asmodeus: Cadeia do Desejo",
  str_monster_passiveskill_desc_29034001 = "Quando um dos Asmodeus conectado pela Cadeia do Desejo sofrer dano ou recuperar HP, o outro Asmodeus sofrerá a mesma quantidade de dano ou recuperará a mesma quantidade de HP. Depois que Asmodeus entrar em ação, as Regiões Escuras serão geradas sob a Cadeia do Desejo.",
  str_monster_passiveskill_name_29034002 = "Asmodeus: Trocar",
  str_monster_passiveskill_desc_29034002 = "Antes de Asmodeus entrar em ação, seus dois corpos podem trocar de posição para facilitar a caça aos alvos.",
  str_monster_passiveskill_name_2903401 = "Asmodeus: Cadeia de Pesadelos",
  str_monster_passiveskill_desc_2903401 = "Aurorianos conectados pela Cadeia de Pesadelos sofrerão dano para cada ladrilho que atravessarem. Deixar o alcance efetivo da Chain of Nightmares irá quebrá-la.",
  str_monster_passiveskill_name_2903411 = "Asmodeus: Separação da Alma",
  str_monster_passiveskill_desc_2903411 = "Quando o elo entre os aurorianos e a Cadeia dos Pesadelos é rompido, os aurorianos recebem um alto dano.",
  str_monster_name_2903501 = "Cerritus",
  str_monster_name_2903501_en = "Cerritus",
  str_monster_desc_2903501 = "O novo Eclipsite encontrado durante a exploração parece ser uma variante de um poderoso Eclipsite, exceto que é mais perturbado e muito mais destrutivo.",
  str_monster_ability_2903501 = "Cerritus ataca os aurorianos batendo neles e tem a poderosa habilidade de invocar seixos e mudar o terreno. Cerritus fica mais forte conforme a batalha avança. Ataques que não matam Cerritus apenas o tornam mais forte! A cada poucas rodadas, Cerritus ruge com raiva e entra em um estado de loucura.",
  str_monster_passiveskill_name_29034011 = "Cerritus: Uivo Irritado",
  str_monster_passiveskill_desc_29034011 = "A cada 2 rodadas, Cerritus uiva furiosamente e cura, ganhando ATK e movimento, mas perdendo DEF. Ao mesmo tempo, convoca Pebbles por todo o campo.",
  str_monster_passiveskill_name_29034012 = "Cerritus: Uivo Irritado",
  str_monster_passiveskill_desc_29034012 = "A cada 2 rodadas, Cerritus uiva furiosamente e cura, ganhando ATK e movimento, mas perdendo DEF. Ao mesmo tempo, convoca Pebbles por todo o campo.",
  str_monster_passiveskill_name_2903501 = "Cerritus: Uivo Irritado",
  str_monster_passiveskill_desc_2903501 = "A cada 2 rodadas, Cerritus uiva furiosamente e cura, ganhando ATK e movimento, mas perdendo DEF. Ao mesmo tempo, convoca Pebbles por todo o campo.",
  str_monster_passiveskill_desc_2903504 = "A cada 2 rodadas, Cerritus uiva furiosamente e cura, ganhando ATK e movimento. Ao mesmo tempo, convoca Pebbles por todo o campo.",
  str_monster_ability_9200164 = "Usa uma lança para atacar alvos e pode aprimorar outros Eclipsites.",
  str_monster_name_21600381 = "Phantom",
  str_monster_name_2902902 = "Jormungand",
  str_monster_name_2902902_en = "Jormungand",
  str_monster_desc_2902902 = "Um Eclipsita nascido nas condições extremas do fim dos tempos. Tem uma figura distorcida e há muito perdeu a capacidade de pensar com inteligência. Tudo o que resta é o desejo de seguir em frente e devorar tudo em seu caminho.",
  str_monster_ability_2902902 = "A estrutura do corpo de Jormungand permite que ele se replique a qualquer momento. Ele devora qualquer obstáculo em seu caminho, até mesmo seu próprio corpo.",
  str_monster_passiveskill_name_2902902 = "Jormungand: Insaciável",
  str_monster_passiveskill_desc_2902902 = "Jormungand ataca novamente sempre que um auroriano usa uma habilidade ativa.",
  str_monster_passiveskill_name_2902901 = "Jormungand: Replicação",
  str_monster_passiveskill_desc_2902901 = "No início da rodada dos monstros, Jormungand se auto-replica, crescendo em 1 novo segmento.",
  str_monster_passiveskill_name_2900251 = "Esquiva",
  str_monster_passiveskill_desc_2900251 = "Move-se com extrema agilidade e tem chance de desviar de ataques. (Não pode esquivar quando Paralisado.)",
  str_monster_name_2002001 = "Venomix",
  str_monster_desc_2002001 = "Diz-se ser um parente distante de uma espécie de Eclipsite capaz de se autodetonar, exceto que esta variedade pode lançar bolas de lodo venenosas, causando danos significativos aos organismos vivos.",
  str_monster_ability_2002001 = "Pulveriza veneno em linha reta ou no local de um auroriano, infligindo veneno no inimigo e seus aliados dentro do alcance do veneno.",
  str_monster_ability_2904201 = "Tem a capacidade de atacar aurorianos à distância e pode lançar ataques em tela cheia. Pode convocar fantasmas que não podem atacar, mas cercam os aurorianos.",
  str_monster_passiveskill_name_2904201 = "Decepção",
  str_monster_passiveskill_desc_2904201 = "Quando a invencibilidade termina, 2 Fantasmas Dreamwalker são convocados para cercar os aurorianos. Fantasmas não podem atacar e não podem ser atacados.",
  str_monster_passiveskill_desc_2904203 = "Quando a invencibilidade termina, 2 Fantasmas Dreamwalker são convocados para cercar os aurorianos. Fantasmas não podem ser atacados.",
  str_monster_name_2904001 = "bennuguardiano",
  str_monster_name_2904001_en = "Bennuguardian",
  str_monster_desc_2904001 = "Um antigo guardião residente nas profundezas do Território Secreto, despertado devido a frequentes distúrbios de intrusos. Mesmo os Eclipsitas têm medo de suas poderosas habilidades. Vaga pelo campo de batalha sem rumo.",
  str_monster_ability_2904001 = "Possui grande poder. Acumula Fúria quando atacado. Quando Fury atinge um certo nível, entra em um estado Enfurecido, reduzindo o dano recebido e lançando habilidades poderosas adicionais. Se o Bennuguardian for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total.",
  str_monster_name_2904202 = "Dreamwalker Aparição",
  str_monster_passiveskill_name_29040011 = "Renascimento Bennu",
  str_monster_passiveskill_desc_29040011 = "Se o Bennuguardian for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total. Suas pilhas de Fúria são limpas ao mesmo tempo.",
  str_monster_passiveskill_name_29040012 = "Fúria de Bennu",
  str_monster_passiveskill_desc_29040012 = "Bennuguardian acumula Fúria quando atacado. Quando o Fury atinge 50 acúmulos, ele entra em um estado Enfurecido, reduzindo o dano recebido e lançando uma poderosa habilidade de ataque adicional após agir a cada rodada. Depois de lançar esta habilidade, o estado Enfurecido de Bennuguardian desaparece.",
  str_monster_name_2002101 = "Cozen",
  str_monster_name_2002101_en = "Cozen",
  str_monster_desc_2002101 = "Possui uma notável capacidade de se misturar com o ambiente. Às vezes, até parece uma armadilha comum. No entanto, uma vez que se revela, irrompe em uma fúria assassina.",
  str_monster_ability_2002101 = "Geralmente se esconde em Crud. Quando a contagem regressiva termina, ele aparece e ataca os aurorianos.",
  str_monster_passiveskill_name_2002101 = "cru",
  str_monster_passiveskill_desc_2002101 = "Quando a contagem regressiva do Crud termina, Cozen aparece e ataca os aurorianos.",
  str_monster_name_2904301 = "Regal",
  str_monster_name_2904401 = "Requiem",
  str_monster_name_2904501 = "Frostfire",
  str_monster_name_2904601 = "Mythos",
  str_monster_name_2904301_en = "Regal",
  str_monster_name_2904401_en = "Requiem",
  str_monster_name_2904501_en = "Frostfire",
  str_monster_name_2904601_en = "Mythos",
  str_monster_passiveskill_name_2904301 = "Geada Regal",
  str_monster_passiveskill_desc_2904301 = "Tem capacidade de contra-ataque. Ganha 1 pilha de Vis cada vez que os aurorianos lançam habilidades ativas. Quando Vis atinge 10 acúmulos, ganha um efeito de aumento de ATK acumulável no início da rodada dos monstros. Dura até o final da batalha.",
  str_monster_passiveskill_name_2904401 = "Réquiem Quebra Tabu",
  str_monster_passiveskill_desc_2904401 = "Tem capacidade de contra-ataque. Ganha 1 pilha de Vis cada vez que os aurorianos lançam habilidades ativas. Quando Vis atinge 10 stacks, lança um ataque em tela cheia no início da rodada dos monstros, causando dano a todos os alvos.",
  str_monster_passiveskill_name_2904501 = "Fogo Congelado: O Crash",
  str_monster_passiveskill_desc_2904501 = "Tem capacidade de contra-ataque. Ganha 1 pilha de Vis cada vez que os aurorianos lançam habilidades ativas. Quando Vis chega a 10 stacks, marca uma área do campo, e no início da rodada dos monstros, desfere dano severo na área marcada.",
  str_monster_passiveskill_name_2904601 = "Cantiga de roda: A Caçada",
  str_monster_passiveskill_desc_2904601 = "Tem capacidade de contra-ataque. Ganha 1 pilha de Vis cada vez que os aurorianos lançam habilidades ativas. Quando Vis chega a 10 stacks, marca uma área do campo, e no início da rodada dos monstros, desfere dano severo na área marcada.",
  str_monster_name_2904101 = "Yoh",
  str_monster_name_2904101_en = "Yoh",
  str_monster_desc_2904101 = "Outrora o líder do peixe-serpente, ele foi escravizado pelos aurorianos para servir como ferramenta de navegação. Anos de ódio crescente o transformaram em um demônio poderoso.",
  str_monster_ability_2904101 = "Possui poderosas habilidades mágicas e pode controlar projéteis para causar dano aos inimigos.",
  str_monster_name_2002202 = "Palavra",
  str_monster_desc_2002202 = "Yoh projeta palavras em sua mente na realidade para atacar seus inimigos.",
  str_monster_ability_2002202 = "Quando a ilusão não está ativa, Yoh controla \"Palavras\", arremessando-as como projéteis para atingir diretamente os aurorianos. (Os aurorianos podem destruir projéteis durante este período para evitar danos.)",
  str_monster_desc_49031011 = "Uma integrante da Equipe Técnica da Rediesel Wrench altamente confiante em suas tecnologias de comunicação. Gosta de gritar e reclamar de todos no Canal de Comunicação, mas se afoba quando há problemas.",
  str_monster_ability_4903103 = "Sempre se move para o local mais distante do alvo. A habilidade causa dano em grande área. A habilidade carregável causa dano em tela cheia e repele os alvos.",
  str_monster_ability_4900232 = "Vani pode usar energia para atacar à distância.",
  str_monster_passiveskill_name_48004341 = "Reviver",
  str_monster_passiveskill_desc_48004341 = "Mara Sol recupera 50% do HP quando está perto da morte e, em seguida, ganha a habilidade de contra-atacar, mas também recebe dano aumentado. Esta habilidade passiva só pode ser acionada uma vez.",
  str_monster_passiveskill_name_48004342 = "Abismo",
  str_monster_passiveskill_desc_48004342 = "Entra em vigor depois que Mara Sol revive. Sempre que um Aurorian lança uma Habilidade Ativa, Mara Sol invoca um Chasm para o campo.",
  str_monster_ability_4000124 = "Um Eclipsite com habilidades de invocação de baixo nível. Incapaz de se mover sozinho e luta invocando Chasms.",
  str_monster_name_2002301 = "Assistente Afônico",
  str_monster_desc_2002301 = "Possível um certo tipo de \"mentor\" do Eclipsite, visto que ambos curam outros Eclipsites. A diferença é que este Eclipsite tem mais chances de ficar perto de seus aliados mais volumosos para aproveitar ao máximo o efeito especial de sua habilidade.",
  str_monster_ability_2002301 = "O Assistente Afônico se move na direção com o maior número de Eclipsitas. Pode restaurar o HP de outros Eclipsitas. Quanto mais peças ocupadas por outros Eclipsitas dentro do alcance da habilidade do Assistente Afônico, mais forte será o efeito de sua cura.",
  str_monster_name_2904801 = "Verme da areia rosa",
  str_monster_name_2904801_en = "Pink Sandworm",
  str_monster_desc_2904804 = "Um raro verme da areia nativo do Deserto de Rediesel. Ele é coberto de escamas rosa devido a uma mutação única, tornando-o mais poderoso e mais feroz do que outros vermes da areia. Por causa de sua aparência rara e especial, certos prevaricadores sem escrúpulos afirmam que suas escamas são tesouros raros que podem ser transformados em uma poção mágica que pode realizar todos os desejos de alguém, mas na verdade são apenas escamas cor-de-rosa comuns sem nenhuma funcionalidade especial. .",
  str_monster_ability_2904801 = "Perfura o solo para encontrar a localização de seu alvo e, em seguida, explode em campo aberto. Excelente em cuspir areia negra para atacar alvos à sua frente.",
  str_monster_name_2904701 = "caçador mecânico",
  str_monster_name_2904701_en = "Mechanical Huntsman",
  str_monster_desc_2904701 = "Um antigo guardião criado com o único propósito de proteger os segredos desta terra. É difícil escapar de seus ataques e ele também tem uma auto-recuperação incrível para mantê-lo funcionando através dos tempos. Ninguém vai querer enfrentá-lo sozinho.",
  str_monster_ability_2904701 = "Cria uma zona protegida dentro de 2 grupos circundantes de si mesmo a cada rodada. Os aurorianos dentro da zona protegida sofrerão dano adicional sempre que atacarem ou se moverem. Se o Mechanical Huntsman for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total.",
  str_monster_name_2904901 = "os quatro cavaleiros",
  str_monster_name_2904901_en = "os quatro cavaleiros",
  str_monster_desc_2904901 = "Embora pareçam membros comuns do júri, os capacetes de gesso em suas cabeças os fazem parecer muito suspeitos. Acontece que são Eclipsites escondidos sob eles! O mais confuso é que eles parecem estar seguindo as instruções de alguém...",
  str_monster_ability_2904901 = "Os Quatro Cavaleiros têm ataques poderosos e excelentes habilidades de teletransporte. Sempre que 1 dos Quatro Cavaleiros for atacado ou recuperar HP, os outros cavaleiros sofrerão a mesma quantidade de dano ou recuperarão a mesma quantidade de HP.",
  str_monster_passiveskill_name_2904901 = "Os Quatro Cavaleiros: Mútuo",
  str_monster_passiveskill_desc_2904901 = "Sempre que 1 dos Quatro Cavaleiros for atacado ou recuperar HP, os outros cavaleiros sofrerão a mesma quantidade de dano ou recuperarão a mesma quantidade de HP.",
  str_monster_name_2905501 = "Demônio Hati",
  str_monster_name_2905501_en = "Demônio Hati",
  str_monster_desc_2905501 = "Memórias do passado inundaram seu coração, criando o temível Demon Hound quando o ódio assumiu o controle.",
  str_monster_ability_2905501 = "Quando Demon Hati está à beira da morte, ela pode consumir energia regenerativa para restaurar seu HP total. Ela também lançará uma habilidade poderosa e se aprimorará. Demon Hati causa mais dano à medida que seu HP diminui e contra-ataca habilidades ativas.",
  str_monster_ability_2905502 = "Demon Hati consome uma parte de seu HP para atacar e recupera uma parte de seu HP perdido se algum auroriano for atingido. Demon Hati causa mais dano à medida que seu HP diminui!",
  str_monster_ability_2905503 = "Quando Demon Hati está à beira da morte, ela pode consumir energia regenerativa para restaurar seu HP total. Ela também lançará uma habilidade poderosa e se aprimorará. Demon Hati causa mais dano à medida que seu HP diminui!",
  str_monster_ability_2905504 = "Quando Demon Hati está à beira da morte, ela pode consumir energia regenerativa para restaurar seu HP total. Ela também lançará uma habilidade poderosa e se aprimorará. Demon Hati causa mais dano à medida que seu HP diminui e contra-ataca habilidades ativas.",
  str_monster_passiveskill_name_2905501 = "Demônio Hati: Recuperação",
  str_monster_passiveskill_desc_2905501 = "Quando Demon Hati está com HP baixo, ela consome energia regenerativa para se restaurar ao HP total.",
  str_monster_passiveskill_name_2905502 = "Demônio Hati: Chamas Nether",
  str_monster_passiveskill_desc_2905502 = "Sempre que Demon Hati consome energia regenerativa, ela se torna Demon Hati: Ominous Flame nesta rodada, se teletransporta ao lado de Aurorians e consome 15% de seu HP atual para causar dano massivo a Aurorians. Se ela atingir um alvo, recupera 15% de seu HP perdido.",
  str_monster_passiveskill_name_2905503 = "Demônio Hati: Sustento",
  str_monster_passiveskill_desc_2905503 = "Demon Hati recupera parte de seu HP perdido ao causar dano a aurorianos.",
  str_monster_passiveskill_name_2905504 = "Demônio Hati: Feral",
  str_monster_passiveskill_desc_2905504 = "Quanto menor o HP do Demon Hati, maior o dano causado pela habilidade.",
  str_monster_passiveskill_name_2905505 = "Demônio Hati: Retaliar",
  str_monster_passiveskill_desc_2905505 = "Sempre que um auroriano usa uma habilidade ativa, o Demon Hati se teletransporta para os aurorianos o mais próximo possível dentro de 1 cluster ao redor e, em seguida, ataca os alvos dentro de 1 cluster ao redor.",
  str_monster_passiveskill_name_2905506 = "Demônio Hati: Retaliar",
  str_monster_passiveskill_desc_2905506 = "Sempre que um auroriano usa uma habilidade ativa, o Demon Hati se teletransporta para os aurorianos o mais próximo possível dentro de 2 grupos ao redor e, em seguida, ataca os alvos em 1 grupo ao redor.",
  str_monster_name_2905101 = "Sondador",
  str_monster_name_2905101_en = "Driller",
  str_monster_desc_2905101 = "Um robô de combate desenvolvido pela Illumina. Ele teve um desempenho extremamente bom em testes internos, mas ainda não foi testado em combate real.",
  str_monster_ability_2905101 = "O perfurador tem 2 estados. Ele se move pelo campo em seu estado normal e cava um certo número de Campos de Energia e Campos de Suporte a cada rodada. Quando há um certo número de Campos de Energia no campo, ele absorve e monta uma Plataforma de Perfuração.",
  str_monster_name_2905102 = "Plataforma de Perfuração",
  str_monster_name_2905102_en = "Driller Platform",
  str_monster_name_2905001 = "Rainha Aranha",
  str_monster_name_2905001_en = "Spider Queen",
  str_monster_desc_2905001 = "Este Eclipsite especial se assemelha a aranhas e aprendeu o comportamento de grupos de aranhas durante seu caminho evolutivo. Ele se esconde na escuridão onde a luz do sol não pode chegar.",
  str_monster_ability_2905001 = "Possuindo fortes habilidades reprodutivas, tece teias de aranha em um ambiente de caça.",
  str_monster_name_2002401 = "filhote de aranha",
  str_monster_desc_2002401 = "Descendentes da Rainha Aranha que têm autoconsciência fraca e seguem todos os seus comandos.",
  str_monster_ability_2002401 = "Sob as ordens da Rainha Aranha, os Filhotes de Aranha se reúnem e atacam suas presas como um grupo.",
  str_monster_passiveskill_name_2002401 = "Rastreamento da Web",
  str_monster_passiveskill_desc_2002401 = "Filhotes de aranha apenas rastejam ao longo da teia e criarão seu próprio caminho quando não houver para onde ir.",
  str_monster_name_2905201 = "Figerald",
  str_monster_name_2905201_en = "Figerald",
  str_monster_desc_2905201 = "Como um dos Wraiths mais poderosos, ele ataca com todas as suas forças quando seu status é ameaçado.",
  str_monster_ability_2905201 = "Tem o poder de destruir o meio ambiente e sempre mantém uma certa distância dos aurorianos.",
  str_monster_name_2002501 = "Soldados Illumina",
  str_monster_desc_2002501 = "Soldados de combate comuns do Exército Illumina, conhecidos por sua habilidade com rifles e facas de combate, bem como sua tenacidade, ética de trabalho, proatividade em batalha e espírito de luta destemido.",
  str_monster_ability_2002501 = "Usa mais ataques à distância. Quando a batalha é intensa, avança rapidamente aos inimigos e enfrenta-os em combate corpo a corpo para derrotá-los o mais rápido possível.",
  str_monster_ability_2002502 = "Um habilidoso combatente corpo a corpo com a capacidade de detectar e reagir aos movimentos do inimigo durante batalhas intensas, permitindo contra-ataques eficazes.",
  str_monster_passiveskill_name_200250103 = "Tenacidade de Batalha",
  str_monster_passiveskill_desc_200250103 = "Quando o HP estiver abaixo de 50%, todos os ataques com armas se tornarão ataques corpo a corpo com uma faca de combate. Ao mesmo tempo, todos os hematomas acumulados se transformarão em HP restaurado e aumentarão ATK e DEF.",
  str_monster_passiveskill_name_200250113 = "Contra-ataque Afiado",
  str_monster_passiveskill_desc_200250113 = "Cada vez que o inimigo usa uma Habilidade Ativa, os Soldados Illumina avançam 1 ladrilho e atacam.",
  str_monster_name_2905301 = "Hélios de teste de estado",
  str_monster_name_2905301_en = "Helios de teste de estado",
  str_monster_desc_2905301 = "Depois de viver sozinho por mais de uma década na Dark Zone, este soldado Illumina esqueceu tudo, exceto lutar. O mais assustador é que ele ficou mais forte na batalha depois de ser modificado por alguém...",
  str_monster_ability_2905301 = "Uma entidade que possui fortes habilidades de combate e acumula Contusões ao receber dano. Quando seus ataques erram o alvo, uma Marca do Terror é lançada no campo. As habilidades de Helios se tornam mais poderosas com cada Terror Mark no campo.",
  str_monster_passiveskill_name_29053011 = "Implacável",
  str_monster_passiveskill_desc_29053011 = "Ao receber dano, Helios acumula Contusões iguais a 50% do dano recebido.",
  str_monster_passiveskill_name_29053012 = "Marca do Terror",
  str_monster_passiveskill_desc_29053012 = "Quando o Dread Rush ou Leap of Terror de Helios erra seus alvos, uma Marca de Terror é lançada no campo: ele causa dano ao alvo diretamente e gera uma marca no ladrilho em que o alvo está.",
  str_monster_passiveskill_name_2904701 = "Revive: Contador",
  str_monster_passiveskill_desc_2904701 = "Se o Mechanical Huntsman for invencível quando entrar em ação, ele consumirá sua energia regenerativa para restaurar seu HP total. Na próxima rodada após a recuperação, o Mechanical Huntsman usará uma habilidade extremamente perigosa que reduz o HP dos aurorianos dentro da zona protegida para 1.",
  str_monster_passiveskill_name_2905102 = "Desmontagem da Plataforma do Perfurador",
  str_monster_passiveskill_desc_2905102 = "O Perfurador e a Plataforma do Perfurador possuem HP independente. No modo Driller Platform, os jogadores podem atacar o Driller que está escondido atrás da plataforma. Se a plataforma do perfurador se tornar invencível, ela será desmontada automaticamente para revelar o perfurador.",
  str_monster_passiveskill_name_2905101 = "Controle do Sondador",
  str_monster_passiveskill_desc_2905101 = "Quando o Driller entra em ação, se houver 6 Campos de Energia no campo, ele convoca a Plataforma do Perfurador, que ocupa 5 ladrilhos onde está parado.",
  str_monster_name_2905401 = "Joshua: Alma Maculada",
  str_monster_name_2905401_en = "Joshua: Tainted Soul",
  str_monster_desc_2905401 = "A invasão da matéria maligna traz agonia e angústia implacáveis... Sua existência, nunca destinada a este mundo, foi trazida por ele...",
  str_monster_ability_2905401 = "Ela tem imenso controle sobre o ambiente e é parcialmente resistente aos ataques e habilidades normais dos aurorianos.",
  str_monster_name_2003201 = "Mime Kartima",
  str_monster_name_2003201_en = "Mime Kartima",
  str_monster_desc_2003201 = "\"Vou salvaguardar a honra de Kartimas.\"",
  str_monster_ability_2003201 = "Enquanto segura um escudo para defesa, Mime Kartima alternará habilmente entre um mangual e um escudo para atingir o alvo de acordo com seu posicionamento.",
  str_monster_name_2003202 = "Lumopolis Hammerguard",
  str_monster_name_2003202_en = "Lumopolis Hammerguard",
  str_monster_desc_2003202 = "Revisado: Os guardiões de elite de Lumopolis, seus escudos e armaduras impenetráveis permanecem como fortalezas, enquanto os estrondosos golpes de martelo ecoam como poderosas avalanches.",
  str_monster_ability_2003202 = "Enquanto segura um escudo para defesa, Mime Kartima alternará habilmente entre um mangual e um escudo para atingir o alvo de acordo com seu posicionamento.",
  str_monster_passiveskill_name_200320105 = "Kartima: Shieldguard",
  str_monster_passiveskill_desc_200320105 = "Kartima brande seu escudo, reduzindo o dano de ataques frontais. Perde o efeito quando atordoado, amedrontado, paralisado ou infligido com outros efeitos de controle.",
  str_monster_passiveskill_name_200320106 = "Kartima: Inflexível",
  str_monster_passiveskill_desc_200320106 = "Kartima fica imune a Stun, Frighten, Paralysis e outros efeitos de controle por 2 rodadas após entrar na batalha",
  str_monster_passiveskill_desc_200320107 = "Kartima fica imune a Stun, Frighten, Paralysis e outros efeitos de controle por 1 rodada após entrar na batalha",
  str_monster_passiveskill_desc_200320108 = "Kartima fica imune a Stun, Frighten, Paralysis e outros efeitos de controle por 3 rodadas após entrar na batalha",
  str_monster_passiveskill_desc_200320109 = "Kartima fica imune a Stun, Frighten, Paralysis e outros efeitos de controle por 5 rodadas após entrar na batalha",
  str_monster_passiveskill_name_200320205 = "protetor de escudo",
  str_monster_passiveskill_desc_200320205 = "Lumopolis Hammerguard brande seu escudo, reduzindo o dano de ataques frontais. Perde o efeito quando atordoado, amedrontado, paralisado ou infligido com outros efeitos de controle.",
  str_monster_passiveskill_name_200320206 = "Inflexível",
  str_monster_passiveskill_desc_200320206 = "Imune a Stun, Frighten, Paralysis e outros efeitos de controle por 2 rodadas após entrar na batalha",
  str_monster_passiveskill_desc_200320207 = "Imune a Stun, Frighten, Paralysis e outros efeitos de controle por 1 rodada após entrar na batalha",
  str_monster_passiveskill_desc_200320208 = "Imune a Stun, Frighten, Paralysis e outros efeitos de controle por 3 rodadas após entrar na batalha",
  str_monster_passiveskill_name_39002111 = "Clamor de Pedra",
  str_monster_passiveskill_desc_39002111 = "Umbrahulk convoca Pebbles aleatoriamente no campo de batalha no final de cada rodada",
  str_monster_passiveskill_name_3900452 = "poder abandonado",
  str_monster_passiveskill_desc_3900452 = "Quando monstros Renegados recebem dano, o efeito do contador de elemento aumenta em 100%.\nMonstros abandonados irão se aprimorar continuamente de acordo com o dano que recebem.",
  str_monster_passiveskill_name_3900453 = "poder abandonado",
  str_monster_passiveskill_desc_3900453 = "Monstros abandonados irão se aprimorar continuamente de acordo com o dano que recebem.",
  str_monster_name_2904804 = "Abandonado: Verme da Areia Rosa",
  str_monster_name_2904804_en = "Forsaken: Pink Sandworm",
  str_monster_name_4904901 = "Abandonado: Os Quatro Cavaleiros",
  str_monster_name_4904901_en = "Forsaken: The Four Knights",
  str_monster_name_39038011 = "Abandonado: Astor",
  str_monster_name_39038011_en = "Forsaken: Astor",
  str_monster_name_3100311 = "Desamparado: Augeano",
  str_monster_name_3100311_en = "Forsaken: Augean",
  str_monster_desc_3900311 = "Forsaken: Augean torna-se imune a todos os ataques aurorianos e convoca um clone para enfrentar o jogador. O dano infligido ao clone é transferido para o corpo principal.",
  str_monster_ability_3100311 = "Revive um clone a cada rodada. O clone pode atacar alvos várias vezes e infligir Sangramento. Contador de movimento: Cada vez que os aurorianos usam uma habilidade ativa nesta rodada, o alcance do movimento do clone aumenta.",
  str_monster_name_3100312 = "Clone abandonado",
  str_monster_desc_3900312 = "1. Todos os danos recebidos serão totalmente transferidos para o corpo principal. Não pode ser imune a dano baseado em porcentagem.\n2. O clone terá o mesmo ATK e DEF do corpo principal. O HP máximo do clone aumentará de acordo com a quantidade de dano causado ao corpo principal.",
  str_monster_ability_3100312 = "Os clones podem atacar alvos várias vezes. Contador de movimento: o alcance do movimento do clone aumentará cada vez que os aurorianos usarem uma habilidade ativa durante a rodada atual.",
  str_monster_name_531400511 = "Mia: Lustrous Soul",
  str_monster_name_531400511_en = "Mia: Lustrous Soul",
  str_monster_desc_531400511 = "Um cavaleiro Lumopolis que vive uma vida isolada em Umbraton.",
  str_monster_ability_531400511 = "Ganha um buff de ATK adicional quando o HP está baixo. Concede a si mesmo um escudo a cada 3 rodadas para resistir a danos.",
  str_monster_name_4902501 = "Abandonado: Minos",
  str_monster_name_4902501_en = "Forsaken: Minos",
  str_monster_passiveskill_name_4902501 = "Abandonado: Enfraquecimento Designado",
  str_monster_passiveskill_desc_4902501 = "Gera 4 ladrilhos enfraquecidos em um ladrilho diagonal a cada rodada.",
  str_monster_passiveskill_name_4902502 = "Abandonado: Ataque Fantasma",
  str_monster_passiveskill_desc_4902502 = "Se Abandonado: se Minos passar por um bloco melhorado ou enfraquecido, um fantasma será invocado para causar dano aos Aurorianos.",
  str_monster_name_4900511 = "Abandonado: Nozard",
  str_monster_name_4900511_en = "Forsaken: Nozard",
  str_monster_ability_4900511 = "indignado, Nozard constantemente bate no chão para derrubar o jogador e convoca Gloom Ghouls para ajudá-lo na batalha. Nozard não recebe dano de ataques normais.",
  str_monster_name_2905404 = "Joshua: Escuro Angel",
  str_monster_name_2905404_en = "Joshua: Dark Angel",
  str_monster_name_2905405 = "Joshua: Demônio branco",
  str_monster_name_2905405_en = "Joshua: White Demon",
  str_monster_name_2000255 = "Guarda Lumo Amaldiçoado",
  str_monster_name_2000285 = "Amaldiçoado Lumo Shieldmate",
  str_monster_name_2000295 = "Amaldiçoado Lumo Piker",
  str_monster_desc_2905404 = "Como uma personificação de rancores sem fim, é uma parte dilacerada das emoções de Joshua, uma entidade formidável nascida no vazio, abrigando inimizade contra todas as almas que irradiam amor.",
  str_monster_desc_2905405 = "Um ser impecável convocado das profundezas do chamado de uma mãe. Ele derramou emoções inúteis para alcançar o ideal supremo, o assassino perfeito não afetado por sentimentos.",
  str_monster_desc_2000255 = "Outrora um guarda leal de Lumopolis, agora foi corrompido e levado à loucura por Joshua.",
  str_monster_desc_2000285 = "Mesmo o guardião mais forte não pode resistir à corrupção do mal. May as paredes de Lumopolis sejam puras mais uma vez.",
  str_monster_desc_2000295 = "Naquela época, eles diziam que os portadores de lanças tinham a pior sorte, o que acabou sendo verdade, já que a invasão do mal os tinha como alvo desde o início.",
  str_monster_desc_2000606 = "Nascido de emoções negativas, este Eclipsite rastrearia aqueles sobrecarregados com maldições.",
  str_monster_ability_2905404 = "Libera o poder infinito das maldições, e quando a força da maldição dominar a vida concedida pela luz, a escuridão envolverá tudo.",
  str_monster_ability_2905405 = "Libera o poder infinito das maldições, e quando a força da maldição dominar a vida concedida pela luz, a escuridão envolverá tudo.",
  str_monster_ability_2000255 = "Os guardas, tornados inconscientes por uma maldição, devem se levantar novamente quando entrelaçados pelo Lurker ou na presença de Joshua, liberando o poder da maldição através de seus ataques.",
  str_monster_ability_2000285 = "Companheiros de escudo, inconscientes por uma maldição, ressuscitarão quando entrelaçados pelo Espreitador ou na presença de Joshua, liberando o poder da maldição através de seus ataques.",
  str_monster_ability_2000295 = "Pikers, inconscientes por uma maldição, ressuscitarão quando entrelaçados pelo Lurker ou na presença de Joshua, liberando o poder da maldição através de seus ataques.",
  str_monster_ability_2000606 = "Procura os soldados amaldiçoados de Lumopolis, possuindo-os e fazendo com que os soldados em coma despertem e caiam na loucura.",
  str_monster_passiveskill_name_2000255 = "Amaldiçoado",
  str_monster_passiveskill_desc_2000255 = "Quando você ataca um auroriano amaldiçoado, o ponto de maldição aumenta. Mas após a morte, Aurorian emite uma explosão final de luz, reduzindo o ponto de Maldição.",
  str_monster_passiveskill_desc_4904201 = "Quando a invencibilidade termina, 1 Phantasm é convocado para cercar os aurorianos.",
  str_monster_passiveskill_name_4904202 = "Renascimento da Ilusão",
  str_monster_passiveskill_desc_4904202 = "As ilusões só recebem dano de habilidades e podem transferir uma parte do dano para o Dreamwalker. Após a morte, eles deixam 1 ladrilho quebrado em seus fundamentos antes de reviver na rodada seguinte.",
  str_monster_passiveskill_desc_49042021 = "As ilusões recebem apenas dano de ataques de alvo único e podem transferir uma parte do dano para o Dreamwalker. Após a morte, eles deixam 1 ladrilho quebrado em seus fundamentos antes de reviver na rodada seguinte.",
  str_monster_name_5900404 = "clone de Schummer",
  str_monster_ability_4902501 = "Convoca peças enfraquecidas ao seu redor a cada rodada e absorve peças aprimoradas e enfraquecidas no campo ao atacar. Quanto mais ladrilhos Minos absorve, mais perigoso é o ataque de Minos.",
  str_monster_desc_29009112 = "Um inimigo vil voltou mais uma vez e está determinado a acabar com todos os seus inimigos desta vez.",
  str_monster_passiveskill_name_29001821 = "Do nada: Shadowgeist",
  str_monster_passiveskill_desc_29001821 = "Invoca 2 Shadowgeists em um local aleatório.",
  str_monster_passiveskill_name_29001421 = "Out of the Blue: Gloom Ghoul",
  str_monster_passiveskill_desc_29001421 = "Invoca 2 Gloom Ghouls em um local aleatório.",
  str_monster_ability_29001811 = "Hábil em ataques à distância que irão atordoar o alvo e invocar o Shadowgeist. Quando raivoso, seus ataques normais atingem duas vezes com alcance de habilidade bastante aprimorado e podem convocar 2 Shadowgeists ao mesmo tempo.",
  str_monster_ability_29001411 = "Com habilidades em ataque de curto alcance, seus ataques atordoam o alvo com a habilidade de convocar o Carniceiro. Depois de ficar Raivosa, seus ataques normais viram ataques duplos com alcance melhorado e ela pode convocar 2 Carniceiros ao mesmo tempo.",
  str_monster_passiveskill_name_5900404 = "Schummer: Gêmeo",
  str_monster_passiveskill_desc_5900404 = "Os danos sofridos pelo clone de Schummer serão transferidos para Schummer. Ao se tornar invencível, fica atordoado por 1 rodada, depois recupera todo o seu HP.",
  str_monster_name_2905601 = "Deusa Denuo",
  str_monster_name_2905601_en = "Denuo Goddess",
  str_monster_desc_2905601 = "Uma borboleta extremamente rara, dizem que só aparece perto do Vale Denuo. É reclusa por natureza, com sentidos altamente aguçados. O poder de combate das Denuo Goddesses adultas não deve ser subestimado.",
  str_monster_ability_2905601 = "Eles catalisam o crescimento das plantas através da polinização, protegendo-se enquanto causam enormes danos aos inimigos.",
  str_monster_name_2002601 = "Erva Encantada Sadesiana",
  str_monster_desc_2002601 = "Inicialmente uma forma de vida semelhante a musgo, mas após a Deusa Denuo usar a Lúmina para estimular seu crescimento, ela se transformará em uma planta parecida com flores e ervas.",
  str_monster_ability_2002601 = "Sob a influência catalítica da Deusa Denuo, ela gradualmente evolui para uma planta extremamente mortal.",
  str_monster_name_2002602 = "Erva Encantada Sadesiana",
  str_monster_desc_2002602 = "Inicialmente uma forma de vida semelhante a musgo, mas após a Deusa Denuo usar a Lúmina para estimular seu crescimento, ela se transformará em uma planta parecida com flores e ervas.",
  str_monster_ability_2002602 = "Sob a influência catalítica da Deusa Denuo, ela gradualmente evolui para uma planta extremamente mortal.",
  str_monster_name_2002603 = "Erva Encantada Sadesiana",
  str_monster_desc_2002603 = "Inicialmente uma forma de vida semelhante a musgo, mas após a Deusa Denuo usar a Lúmina para estimular seu crescimento, ela se transformará em uma planta parecida com flores e ervas.",
  str_monster_ability_2002603 = "Sob a influência catalítica da Deusa Denuo, ela gradualmente evolui para uma planta extremamente mortal.",
  str_monster_name_8900181 = "Oblivion inspirador ",
  str_monster_name_8900181_en = "Oblivion Inspirer",
  str_monster_desc_8900181 = "Ela poderia ser a irmã mais nova de alguém também? Apesar de sua impulsividade e ferocidade externas, é evidente que no fundo existe uma alma vulnerável.",
  str_monster_name_8900411 = "Cavaleiro do Esquecimento",
  str_monster_name_8900411_en = "Oblivion Knight",
  str_monster_desc_8900411 = "Ele está envolto em um clima de traição... aliado a uma luta constante contra o destino injusto e uma sede insaciável por paixão.",
  str_monster_name_8000451 = "Lacaio do Esquecimento",
  str_monster_name_8000451_en = "Lacaio do Esquecimento",
  str_monster_name_80011471 = "Perseguidor do Esquecimento",
  str_monster_name_80011471_en = "Perseguidor do Esquecimento",
  str_monster_desc_80011471 = "Ela habita entre a lembrança e o esquecimento, sugerindo que ainda se apega a algo neste mundo.",
  str_monster_ability_533500302 = "Incapaz de se mover por conta própria, luta invocando Burstbugs autodestrutivos.",
  str_monster_name_99005021 = "Abandonado: Solmorph",
  str_monster_name_99005021_en = "Forsaken: Solmorph",
  str_monster_name_99039011 = "Abandonado: Casta",
  str_monster_name_99039011_en = "Forsaken: Casta",
  str_monster_ability_99005021 = "Causa dano inevitável em grande área; possui a habilidade de mudar a cor das casas do tabuleiro.",
  str_monster_ability_99039011 = "Ataca inimigos em alcance corpo a corpo com uma baioneta ou ataca-os à distância com balas.",
  str_monster_desc_9900501 = "Evoluiu do Siforbe, absorveu tanta Lúmina que é incapaz de controlar a cor da luz ao redor.",
  str_monster_passiveskill_name_29060011 = "Luto: Metamorfose",
  str_monster_passiveskill_desc_29060011 = "A cada rodada, evoque um Dawn Floresça em um local definido para restaurar HP; cada Dawn A flor concede um impulso extra de recuperação.",
  str_monster_name_2906001 = "luto Eve",
  str_monster_name_2906001_en = "Grieving Eve",
  str_monster_desc_2906001 = "A dor do isolamento e o medo de ser cortado, essas memórias insuportáveis do passado, moldaram a pessoa conhecida como Eve hoje.",
  str_monster_ability_2906001 = "A cada rodada, evoque um Dawn Floresça em um local definido no campo de batalha, restaurando HP de acordo com o número de Dawn Flores. Em rodadas específicas, ganhe várias pilhas de imunidade e, em seguida, restaure HP na rodada subsequente com base nas pilhas de imunidade.",
  str_monster_name_2006001 = "Dawn Flor",
  str_monster_desc_2006001 = "Essas simples flores brancas, pequenas e comuns, estão entre os confortos mais preciosos em seu coração.",
  str_monster_ability_2006001 = "Concede bônus de recuperação de HP adicional para Grieving Eve.",
  str_monster_ability_2000401 = "Incapaz de se mover ou atacar. Conecta-se ao Invocador Escuro e oferece redução de dano.",
  str_monster_name_2003001 = "Lança-chamas Illumina",
  str_monster_desc_2003001 = "\"Reduzir todos os adversários a cinzas\" - Eles epitomizam a eficiência e a impiedade das forças Illumina. Diante das chamas furiosas, toda vida está em pé de igualdade.",
  str_monster_ability_2003001 = "Acumula Contusões ao receber dano. Causa dano a todos os alvos dentro do alcance de ataque, infligindo Queimar neles e criando incêndios.",
  str_monster_passiveskill_name_2003001 = "Principal do Campo de Batalha",
  str_monster_passiveskill_desc_2003001 = "Ao receber dano, o Lança-chamas Illumina acumula Contusões iguais a 50% do dano recebido.",
  str_monster_name_2002901 = "Tanque Illumina L5",
  str_monster_desc_2002901 = "Criado através de modificações em caminhões, o Tanque Illumina L5 possui uma armadura leve, tornando-o perfeito para fabricação em massa. Seu poder de carga e canhões de disparo rápido eliminam rapidamente as unidades leves inimigas.",
  str_monster_ability_2002901 = "Com base nas posições inimigas, opta por disparar uma rápida saraivada de tiros ou uma investida para ataque.",
  str_monster_name_2003401 = "Soldado Illumina Corrompido",
  str_monster_name_2003401_en = "Soldado Illumina Corrompido",
  str_monster_desc_2003401 = "Uma vez aliados, agora inimigos - tal é o terror do Eclipse. A única misericórdia restante é colocá-los para descansar.",
  str_monster_ability_2003401 = "Cria atoleiros nos azulejos movidos. Quando com poucos PV, aumenta significativamente o ACT e aumenta a DEF.",
  str_monster_passiveskill_name_20034011 = "Mente Corrompida",
  str_monster_passiveskill_desc_20034011 = "Se o HP estiver abaixo de 40% no início de uma rodada, a unidade tem seu ACT e DEF aumentados e seu estilo de ataque alterado.",
  str_monster_passiveskill_name_20034012 = "Passo Corrompido",
  str_monster_passiveskill_desc_20034012 = "Cria pântanos nas casas por onde se move.",
  str_monster_name_2003101 = "Sargento Illumina",
  str_monster_desc_2003101 = "Como oficiais de base do exército Illumina, eles são responsáveis por comandar soldados regulares no campo de batalha. A maioria deles se forma em academias militares, enquanto alguns são promovidos das fileiras de veteranos experientes.",
  str_monster_ability_2003101 = "A presença deles melhora as habilidades dos Soldados Illumina próximos e ajuda na recuperação de seus ferimentos. Caso se encontrem isolados dos aliados ou em combate corpo a corpo com inimigos, esses sargentos pegam em armas, causando danos com cortes devastadores e chutes impactantes.",
  str_monster_name_2002701 = "Médico da Illumina",
  str_monster_desc_2002701 = "Onde quer que o Médico Illumina esteja, o moral aumenta, pois os camaradas sabem que suas feridas não ficarão sem tratamento. A Federação Illumina, ciente deste fato, fornece a esses médicos proteção aprimorada, aumentando significativamente suas capacidades de sobrevivência.",
  str_monster_ability_2002701 = "Um Soldado Illumina sem capacidades de combate. Restaura HP para um Soldado Illumina próximo e cura certos ferimentos para si próprio.",
  str_monster_name_2002801 = "Sinalizador Illumina",
  str_monster_desc_2002801 = "Equipado com um comunicador compacto, o Sinaleiro de Illumina carrega uma carga pesada. Por isso, a Federação Illumina desenvolveu um aparato de suporte especializado, facilitando a transmissão de sinais em movimento, o que é a origem do nome desta unidade.",
  str_monster_ability_2002801 = "Um Soldado Illumina sem capacidades de combate, mas capaz de invocar reforços Illumina no campo de batalha.",
  str_monster_passiveskill_name_2002701 = "Tenacidade no Campo de Batalha",
  str_monster_passiveskill_desc_2002701 = "Ao receber dano, o Médico Illumina acumulará Contusões equivalentes a 50% do dano recebido. Além disso, sua DEF aumenta conforme seu HP diminui.",
  str_monster_name_2003301 = "Tecelão do Pavor",
  str_monster_desc_2003301 = "Movido por uma obsessão em aniquilar tudo, ele ignora a depleção de sua própria energia, perseguindo incansavelmente o objetivo, mesmo que isso signifique caminhar gradualmente em direção à sua própria ruína.",
  str_monster_ability_2003301 = "Assim que o movimento da equipe terminar, Dreadweaver fará com que a equipe mude imediatamente suas posições, afetando o alcance dos Combos em Cadeia. Quando o HP de Dreadweaver cair abaixo de 50%, ele iniciará um ritual de sacrifício - Na próxima rodada, ele queimará seu HP atual até restar apenas 1 ponto, causando dano verdadeiro aos jogadores igual a múltiplas vezes o HP queimado.",
  str_monster_passiveskill_name_2003301 = "Manipulação Psíônica",
  str_monster_passiveskill_desc_2003301 = "Assim que o movimento da equipe terminar, o Dreadweaver fará com que a equipe mude imediatamente suas posições, afetando a realização dos Combos.",
  str_monster_passiveskill_name_2003302 = "Sacrifício de Sangue",
  str_monster_passiveskill_desc_2003302 = "Quando o HP do Dreadweaver cair abaixo de 50%, ele iniciará um ritual de sacrifício. Na próxima rodada, ele queimará quase todo o seu HP, causando um enorme dano verdadeiro aos jogadores. Este efeito só pode ser acionado uma vez.",
  str_monster_name_7001098 = "Abandonado: Schummer, o Aviduz",
  str_monster_name_7001098_en = "Forsaken: Schummer the Aviduz",
  str_monster_ability_7001098 = "Convoca raios periodicamente. O Poder do Raio paralisará os alvos atingidos. O Grito do Colosso pode atrair Aurorianos em direção ao conjurador.",
  str_monster_name_2906101 = "Corrompido Engine VII",
  str_monster_name_2906101_en = "Corrupted Engine VII",
  str_monster_desc_2906101 = "Originalmente um robô de combate colossal criado pela Illumina, ele se tornou uma das maiores ameaças depois que seu piloto perdeu a razão devido à contaminação pela lama.",
  str_monster_ability_2906101 = "Carrega imprudentemente em direção à Fortaleza Illumina, causando dano aos Aurorianos pelo caminho.",
  str_monster_passiveskill_name_29061011 = "Reparar",
  str_monster_passiveskill_desc_29061011 = "Corrompido Engine VII com invencibilidade ficará paralisado. Ele reparará seus componentes durante esse período e, uma vez concluído o reparo, será implantado novamente para o cerco.",
  str_monster_name_2905701 = "Mudbundle",
  str_monster_name_2905701_en = "Mudbundle",
  str_monster_desc_2905701 = "Dizem ser uma criação de um membro do Eclipse, este Eclipsita é uma fusão de várias características biológicas. Ele cria pântanos aterrorizantes que podem devorar tudo e contaminar o que toca.",
  str_monster_ability_2905701 = "Cria atoleiros e submerge por dentro, obstruindo e interrompendo os movimentos dos Aurorianos, alterando o terreno.",
  str_monster_name_8002005 = "Irridon",
  str_monster_name_8002005_en = "Irridon",
  str_monster_desc_8002005 = "A Juíza Principal da Corte de Justiça Lumo. Ela é gentil, bondosa, firme e um exemplo de dedicação. Em seu âmago, esconde um lado paranoico.",
  str_monster_ability_8002005 = "Situado fora do campo, não pode ser alvo de ataques normais. Compartilha dano com todos os inimigos no campo.",
  str_monster_name_2003501 = "Fera do Gelo",
  str_monster_name_2003501_en = "Fera do Gelo",
  str_monster_desc_2003501 = "Com seu pelo e garras afiadas, este Eclipsita se assemelha incrivelmente a uma fera selvagem, tornando-o bem adequado para infiltrar-se em várias regiões de fronteira para rastreamento, reconhecimento e caça.",
  str_monster_ability_2003501 = "Selecionaria diferentes habilidades com base na posição do Aurorian e, se seu ataque não alcançar nenhum Aurorian, escolherá recuperar seu próprio HP.",
  str_monster_name_2900891 = "Irridon: Eximius",
  str_monster_name_2900891_en = "Irridon: Eximius",
  str_monster_desc_2900891 = "Herdando os sinceros ensinamentos de seu pai e cumprindo todas as suas expectativas, ela se tornou a perfeita Irridon, a maior Juíza Chefe que já se conheceu!",
  str_monster_ability_2900891 = "Antes de cada Combo em Cadeia dos Aurorianos, forma-se um Escudo de Luz para bloquear o dano.\nAumenta todo o dano causado com base no número de acúmulos de Preconceito nos Aurorianos.",
  str_monster_passiveskill_name_29089011 = "Escudo de Luz",
  str_monster_passiveskill_desc_29089011 = "Antes de cada Chain Combo, forma o Escudo de Luz, bloqueando dano equivalente a uma porcentagem do HP máximo.",
  str_monster_passiveskill_name_29089012 = "Wrath do Juiz Chefe",
  str_monster_passiveskill_desc_29089012 = "Possui múltiplos segmentos de HP. No início de cada rodada, se ela tiver perdido um segmento de HP em comparação com a rodada anterior, ela desencadeará o Castigo do Juiz-Chefe, causando dano massivo.",
  str_monster_passiveskill_name_29089021 = "Transmissão de Danos",
  str_monster_passiveskill_desc_29089021 = "O dano causado a Irridon: Clones Eximius é transferido instantaneamente para Irridon: Eximius.",
  str_monster_name_2003601 = "Espectro Carmesim",
  str_monster_desc_2003601 = "Arrogância, preconceito e pensamentos corrompidos... se transformaram em espectros malévolos vagando por Lumópolis, infiltrando-se em cada fenda desta cidade eterna.",
  str_monster_ability_2003601 = "Pode se teletransportar para a localização do jogador mais próximo, desferindo vários golpes prejudiciais e empurrando o jogador para trás. Quanto mais longe ele se teletransporta, menos ataques ele lança.",
  str_monster_name_2902131 = "No. 33: O Guardião Sem Nome",
  str_monster_name_2902131_en = "No. 33 - The Nameless Keeper",
  str_monster_desc_2902131 = "Uma antiga Aurorian, guardiã das ruínas subterrâneas em Northland. Ela viveu sozinha por anos, até suas memórias começarem a desaparecer.",
  str_monster_ability_2902131 = "Capaz de realizar ataques à distância em Aurorians de qualquer lugar; Pode alterar os elementos das casas ao redor de outros Aurorians e de si mesmo.",
  str_monster_passiveskill_name_290213101 = "Controle de Área",
  str_monster_passiveskill_desc_290213101 = "Após sua ação terminar em cada rodada, ele converte os elementos das peças nos 2 agrupamentos ao redor.",
  str_monster_ability_5353002 = "Proficiente em ataques à distância e AoE; entra em um estado Raivoso quando o HP cai abaixo de 30%, liberando continuamente habilidades de dano em tela cheia. Neutraliza 1 habilidade ativa por rodada e lança 5 pilhas de escudo de contagem para autoproteção.",
  str_monster_ability_5353007 = "Causa dano em uma área específica e empurra as unidades inimigas.",
  str_monster_passiveskill_name1_2900401 = "Raivoso",
  str_monster_passiveskill_desc1_2900401 = "Cai em um estado Rabid quando o HP está baixo: libere Colossus: Sonic Blast para ataques em tela cheia a cada rodada.",
  str_monster_passiveskill_name2_2900401 = "Escudo Devorador",
  str_monster_passiveskill_desc2_2900401 = "Cerca-se de 5 pilhas de escudo de contagem, cada uma oferecendo imunidade a danos 1 vez (o contador é limitado a apenas 1 vez por rodada).",
  str_monster_passiveskill_name_5353004 = "Invocação do Carniçal Sombrio",
  str_monster_passiveskill_desc_5353004 = "Invoca um Gloom Ghoul em um local aleatório.",
  str_monster_name_2902801 = "Sanki",
  str_monster_name_2902801_en = "Sanki",
  str_monster_desc_2902801 = "\"Quando o mal chama nas flores de cerejeira, o Sakae foge, abandonado pelo povo; apenas um em dez sobrevive.\" Com os alvos à vista, sua batalha por vingança começa aqui.",
  str_monster_ability_2902801 = "Sanki possui alta mobilidade, realizando uma carga rápida a cada poucos turnos para se aproximar do alvo e causar dano rapidamente. A cada movimento, Sanki lança Lâminas Sakae no campo, apenas para recuperá-las no próximo movimento, causando enormes danos aos alvos inimigos ao longo de seus caminhos.",
  str_monster_name_70011021 = "Abandonado: Sanki",
  str_monster_name_70011021_en = "Forsaken: Sanki",
  str_monster_passiveskill_name_2902801 = "Sakae: Controle",
  str_monster_passiveskill_desc_2902801 = "Antes de Sanki agir, ele lança Lâminas Sakae em quatro direções pelo campo, apenas para recuperá-las todas no próximo movimento. As Lâminas Sakae causam enormes danos às unidades inimigas ao longo de seus caminhos quando lançadas ou recuperadas.",
  str_monster_name_70011023 = "Abandonado: Brock",
  str_monster_name_70011023_en = "Forsaken: Brock",
  str_monster_desc_70011023 = "Membro da equipe Parafusos Soltos da Rediesel Wrench, Brock é um cabeça-quente e autoconfiante que às vezes faz coisas tolas para satisfazer sua natureza competitiva.",
  str_monster_ability_70011023 = "Com um notável ATQ e ACT, Brock também pode atrair inimigos para sua proximidade através de sua habilidade suprema.",
  str_monster_name_70011041 = "Abandonado: Schwartz",
  str_monster_name_70011041_en = "Forsaken: Schwartz",
  str_monster_desc_70011041 = "O governador de Lumópolis, o maior governante, é conhecido por sua dedicação altruísta. Ele pode até mesmo visitar a arena pessoalmente para avaliar a habilidade de todos.",
  str_monster_ability_70011041 = "Schwartz aproveita um incrível Poder do Relâmpago, concedendo-lhe um nível temível de mobilidade e força destrutiva. Aqueles que passam em seu formidável teste de força são considerados a nata da nata.",
  str_monster_name_5352021 = "Escudeiro Lumo",
  str_monster_name_5352021_en = "Escudeiro Lumo",
  str_monster_desc_5352021 = "Guardas armados com um escudo de defesa superior. Com a habilidade de aguentar batalhas difíceis, são fortes muralhas que protegem seus companheiros.",
  str_monster_ability_5352021 = "Um guarda valente com capacidades defensivas extraordinárias pode convocar outros soldados de Lumópolis para ajudar na batalha e aumentar o moral deles. Empunha um escudo poderoso que pode ser usado para infligir ataques corpo a corpo devastadores.",
  str_monster_name_2905801 = "Imperador do Fim",
  str_monster_name_2905801_en = "Imperador do Fim",
  str_monster_desc_2905801 = "O Supremo Imperador do Caos, pai de Tohru, veterano de muitas guerras, é uma potência inegável, não importa quando e onde.",
  str_monster_ability_2905801 = "Com força formidável, ele empunha uma infinidade de habilidades para atacar jogadores com precisão ou desencadear ataques de longo alcance, ao mesmo tempo em que os repele.",
  str_monster_passiveskill_name_2905801 = "Enfraquecimento de Lúmina",
  str_monster_passiveskill_desc_2905801 = "Os ataques normais e em cadeia do jogador causam dano reduzido aos 5 ladrilhos ocupados pelo chefe, excluindo o ladrilho central.",
  str_monster_ability_140045106 = "Use Nails",
  str_monster_ability_150092106 = "Causa dano aos inimigos em uma área em forma de X, enquanto converte as casas Vermelhas adversas ao lançador.",
  str_monster_ability_160103106 = "Causa dano ao inimigo mais próximo enquanto converte os ladrilhos Azuis adversos ao lançador.",
  str_monster_ability_160111106 = "Luta usando cristais, causando dano a todos os inimigos no campo de batalha.",
  str_monster_ability_150009106 = "Causa dano aos inimigos em uma área em forma radial e pode infligir Medo nos alvos atingidos.",
  str_monster_ability_160120106 = "Sua armadura gigante, chamada Pompey, pode causar dano em uma grande área e causar dano adicional aos inimigos dentro de 1 aglomerado ao redor.",
  str_monster_ability_160089106 = "Desencadeia continuamente a Chuva da Espada do Brejo Dourado para causar dano aos alvos adjacentes.",
  str_monster_name_39004031 = "Abandonado: Schummer",
  str_monster_name_39004031_en = "Abandonado: Schummer",
  str_monster_desc_39004031 = "Originalmente um Celestita, mas se uniu ao Eclipse e possui poderes melhorados extraordinários.",
  str_monster_ability_39004031 = "Adepto de ataques à distância e de área.",
  str_monster_name_39058011 = "Esquecidos: Imperador do Fim",
  str_monster_name_39058011_en = "Esquecidos: Imperador do Fim",
  str_monster_desc_39058011 = "O Supremo Imperador do Caos, pai de Tohru, veterano de muitas guerras, é uma potência inegável, não importa quando e onde.",
  str_monster_ability_39058011 = "Com força formidável, ele empunha uma infinidade de habilidades para atacar jogadores com precisão ou desencadear ataques de longo alcance, ao mesmo tempo em que os repele.",
  str_monster_ability_5362001 = "Esconde-se na Lumiwall mais distante do jogador; ataques podem mudar o elemento da casa durante sua rota do ataque.",
  str_monster_name_5362001 = "Gronru",
  str_monster_name_5362001_en = "Gronru",
  str_monster_desc_5362001 = "Uma piloto de um robô gigante e atual Oficial de Tecnologia da Federação Illumina. Dizem que ela é um gênio que deixou o exército... Ainda que não pareça interessada em lutar, tem uma obsessão por estudar e controlar máquinas gigantes.",
  str_monster_ability_5362002 = "Adepto de ataques corpo a corpo, causa dano a uma área de coluna.",
  str_monster_desc_5362002 = "Uma integrante da Equipe Técnica da Rediesel Wrench altamente confiante em suas tecnologias de comunicação. Gosta de gritar e reclamar de todos no Canal de Comunicação, mas se afoba quando há problemas.",
  str_monster_ability_5362003 = "Adepto de ataques à distância em área, habilidades infligem Veneno.",
  str_monster_name_2909001 = "Rei Tritão",
  str_monster_name_2909001_en = "Rei Tritão",
  str_monster_desc_2909001 = "Do mundo da superfície à cidade subaquática, um nobre dominador e vilão.",
  str_monster_ability_2909001 = "Ataques causam efeito de empurrão. Pode invocar canhões de salva na borda do campo de batalha.",
  str_monster_passiveskill_name_290900101 = "Implantação de Arma Salvo",
  str_monster_passiveskill_desc_290900101 = "No início de cada rodada do jogador, se houver menos de 2 Salvo Guns no campo de batalha, invoque 4 Salvo Guns na borda do campo de batalha.",
  str_monster_passiveskill_name_290901101 = "Implantação de Arma Salvo",
  str_monster_passiveskill_desc_290901101 = "No início de cada rodada do jogador, se houver menos de 3 Salvo Guns no campo de batalha, invoque 4 Salvo Guns na borda do campo de batalha.",
  str_monster_name_70011101 = "Esquecidos: Diavola",
  str_monster_name_70011101_en = "Esquecidos: Diavola",
  str_monster_desc_70011101 = "Diavola gosta de se esconder e eliminar seus inimigos furtivamente com veneno.",
  str_monster_ability_70011101 = "Diavola não pode se mover. Seu corpo é envolto em grandes e firmes folhas espinhosas que reduzem o dano que recebe.",
  str_monster_passiveskill_name_70011101 = "Folhas Espinhosas",
  str_monster_passiveskill_desc_70011101 = "Reduz o dano recebido nas 8 peças externas da Diavola em 30%.",
  str_monster_passiveskill_name_70011102 = "Folhas Espinhosas",
  str_monster_passiveskill_desc_70011102 = "Reduz o dano recebido nas 8 peças externas da Diavola em 50%.",
  str_monster_name_2003801 = "Capitão da gangue",
  str_monster_desc_2003801 = "O líder peculiar de uma gangue, habilidoso com armas de fogo. Sua presença significa apenas problemas para Umbraton.",
  str_monster_ability_2003801 = "Attacks after moving away from the target, dealing damage 2 times. Can steal the target's attributes.",
  str_monster_passiveskill_name_2003801 = "Tiro Mortal",
  str_monster_passiveskill_desc_2003801 = "Rouba o ATK Básico e a DEF Básica dos Aurorianos ao causar dano. O ATK e DEF roubados serão devolvidos após 2 rodadas ou após esta unidade ser derrotada.",
  str_monster_name_2003701 = "Arqueiro da Gangue",
  str_monster_desc_2003701 = "Precisas, seguras, discretas e incrivelmente poderosas, as bestas se tornaram uma arma adorada entre os gangsters devido a essas propriedades incomparáveis. Inimigos habilidosos em seu uso costumam ser altamente perigosos.",
  str_monster_ability_2003701 = "Pode atacar alvos em forma de cruz até a extensão máxima de seu alcance. Após acertar, reduz a cura recebida pelo alvo.",
  str_monster_passiveskill_name_2003701 = "Flecha Sombria",
  str_monster_passiveskill_desc_2003701 = "Após atingir um Auroriano, reduz em 40% a cura recebida por ele. Este efeito não acumula e é removido quando o Bandido com Besta é derrotado.",
  str_monster_name_2009001 = "Pistola Salvo",
  str_monster_desc_2009001 = "Um Eclipsita que se assemelha a um cano de arma. Fornece suporte aos seus companheiros e ataca sua equipe pesadamente!",
  str_monster_ability_2009001 = "Atira em inimigos dentro do alcance de ataque. Se não houver alvos disponíveis, seu ataque é aprimorado e cura o Rei Tritão.",
  str_monster_name_8003481 = "Dayna",
  str_monster_desc_8003481 = "Apesar de sua pouca idade, ela já é a líder dos Pardais. Conhecida por estabelecer uma forte presença nas ruas de Umbraton com sua determinação incomparável e armas diabólicas e traiçoeiras.",
  str_monster_ability_8003481 = "Ataca o inimigo mais próximo.",
  str_monster_name_8003781 = "Robyn",
  str_monster_desc_8003781 = "Membro dos Pardais de Umbraton. Tímida e introvertida, ela fica sempre por perto de sua irmã, Dayna, enquanto tenta sobreviver em Umbraton.",
  str_monster_ability_8003781 = "Segue o jogador e causa dano em área aos inimigos próximos.",
  str_monster_ability_2300601 = "Os Espreitadores podem se ligar aos Aurorianos dentro de 1 aglomerado ao redor de si mesmos. Uma vez ligados, eles causam dano ao Auroriano e reduzem seu ATK.",
  str_monster_name_2909101 = "Rebecca Pântano Venenoso",
  str_monster_desc_2909101 = "As veias dela pulsam com veneno carmesim, prontas para erradicar qualquer ameaça à sua família, incluindo ela mesma.",
  str_monster_ability_2909101 = "Permite que os ataques causem o efeito Fusão, fazendo com que os alvos afetados percam HP no início de suas rodadas. Evoca Marcas de Veneno nas casas ao redor a cada rodada, impondo Fusão aos inimigos próximos que passam por elas; as Marcas de Veneno se transformam em Casas Escuras no final da rodada.",
  str_monster_name_2003901 = "Especialista em Suporte de Gangue",
  str_monster_desc_2003901 = "Um membro enorme da gangue de força imensa, habilidoso em usar seus braços mecânicos para combate. Além disso, ele pode oferecer suporte a outras forças inimigas de Umbraton no campo de batalha.",
  str_monster_ability_2003901 = "Fornece aumentos de ATK e DEF para membros de Umbraton dentro de 1 aglomerado ao redor; cura-se quando seu HP cai abaixo de uma certa porcentagem.",
  str_monster_passiveskill_name_2003901 = "Suporte Extra",
  str_monster_passiveskill_desc_2003901 = "Fornece aumentos de ATK e DEF aos membros da Umbraton dentro de 1 cluster circundante.",
  str_monster_name_2004101 = "Assassino de Gangue",
  str_monster_desc_2004101 = "\"O melhor golpe é aquele que vem por trás.\" Habilidoso em atacar pontos vitais, as lâminas desta unidade são mortais tanto em brigas de rua quanto no campo de batalha.",
  str_monster_ability_2004101 = "Lança 2 ataques consecutivos rápidos contra o inimigo. Rouba o ATQ básico e DEF dos Aurorianos ao causar dano. O ATQ e DEF roubados serão devolvidos após 2 rodadas ou após esta unidade ser derrotada. Recua após atacar para se proteger. Se o alvo não puder ser atacado, ACT +1 nesta rodada.",
  str_monster_passiveskill_name_2909101 = "Corrosão Tóxica",
  str_monster_passiveskill_desc_2909101 = "Permite que os ataques causem o efeito Fusão, fazendo com que os alvos afetados percam HP no início de suas rodadas. Evoca Marcas de Veneno nas casas ao redor a cada rodada, impondo Fusão aos inimigos próximos que passam por elas; as Marcas de Veneno se transformam em Casas Escuras no final da rodada.",
  str_monster_passiveskill_name_2004101 = "Fervor de Batalha",
  str_monster_passiveskill_desc_2004101 = "Rouba o ATK Básico e a DEF Básica dos Aurorianos ao causar dano. O ATK e DEF roubados serão devolvidos após 2 rodadas ou após esta unidade ser derrotada.",
  str_monster_name_2909101_en = "Rebecca Pântano Venenoso",
  str_monster_name_2003801_en = "Capitão da gangue",
  str_monster_name_70011071 = "Abandonado: Kittypus",
  str_monster_name_70011071_en = "Esquecido: Kittypus",
  str_monster_desc_70011071 = "Um companheiro especial de Gretel. Assemelha-se a um gato com muitas pernas... É fofo, mas de alguma forma perturbador.",
  str_monster_ability_70011071 = "Kittypus libera seus tentáculos, causando dano massivo aos Aurorianos. Lembre-se: os tentaclaws de Kittypus transferem todo dano recebido para seu hospedeiro!",
  str_monster_name_70011081 = "Abandonado: Goldor Sombrio",
  str_monster_name_70011081_en = "Abandonado: Goldor Sombrio",
  str_monster_desc_70011081 = "Eclipsitas encouraçados da Noite Branca, Área Sombria.",
  str_monster_ability_70011081 = "Imóvel, mas pode atacar e empurrar alvos em uma área grande.",
  str_monster_name_70011091 = "Abandonada: Deusa Denuo",
  str_monster_name_70011091_en = "Abandonada: Deusa Denuo",
  str_monster_desc_70011091 = "Uma borboleta extremamente rara. É reclusa por natureza, com sentidos altamente aguçados. O poder de combate não deve ser subestimado.",
  str_monster_ability_70011091 = "Eles catalisam o crescimento das plantas através da polinização, protegendo-se enquanto causam enormes danos aos inimigos.",
  str_monster_ability_70011083 = "Apresentando um nível extremamente baixo de perigo, ele foge imediatamente de medo após os aurorianos usarem suas Habilidades Ativas.",
  str_monster_name_2909201 = "Stinger: Coalescência",
  str_monster_name_2909202 = "Cauda do Ferrão",
  str_monster_name_2909201_en = "Stinger: Coalescência",
  str_monster_desc_2909201 = "Uma arma perigosa criada pela combinação das características mortais de várias criações mecânicas, incluindo tecnologia da Astra. Fontes de energia comuns são incapazes de manter esta criatura gigante funcionando.",
  str_monster_ability_2909201 = "Cada Besta Mecânica que compõe parte de seu corpo possui seu próprio ataque único. A cauda pode acumular Energia para causar dano garantido aos seus alvos, mas também é relativamente frágil.",
  str_monster_passiveskill_name_290920101 = "Armadura Inquebrável",
  str_monster_passiveskill_desc_290920101 = "Ganha um escudo igual a uma porcentagem do HP máximo no início de cada rodada. O escudo restante é convertido em HP ao final da rodada.",
  str_monster_passiveskill_name_290920102 = "Prevenção de Danos",
  str_monster_passiveskill_desc_290920102 = "A cauda do Stinger só pode ser danificada pelas habilidades do Sniper e é imune a ataques normais e danos em área. Quando sua cauda tem zero de HP restante, Stinger fica paralisado por 1 rodada.",
  str_monster_name_2004001 = "Caranguejo Forjado em Fornalha",
  str_monster_desc_2004001 = "Esta criação de ferramenta mecânica foi projetada para ajudar os artesãos a fazer invenções engenhosas. Mais tarde, foi modificada para que uma variação desta invenção pudesse armazenar Força de Chama em seu interior. Nunca foi destinada a ser usada como uma arma.",
  str_monster_ability_2004001 = "Move-se de lado como um caranguejo, balançando suas pinças, e pode cuspir fogo.",
  str_monster_name_70011141 = "Abandonado: Rebecca Pântano Venenoso",
  str_monster_name_70011141_en = "Abandonado: Rebecca Pântano Venenoso",
  str_monster_name_70011151 = "Abandonado: Mudbundle",
  str_monster_name_70011151_en = "Abandonado: Mudbundle",
  str_monster_ability_2003411 = "Cria atoleiros nos ladrilhos movidos. Possuindo DEF extremamente alta, ele irá regenerar e se aprimorar depois de ser devorado.",
  str_monster_name_2906201 = "Vilanor: Armadilha Amaldiçoada",
  str_monster_name_2906201_en = "Vilanor: Armadilha Amaldiçoada",
  str_monster_desc_2906201 = "Uma espada habilmente forjada a partir da engenhosidade do Reino Ye de Longzhou. Originalmente, foi concebida como uma arma de autodefesa para aqueles que não sabiam se defender com uma espada, mas agora se tornou uma espada maligna amaldiçoada após cair nas mãos de vilões.",
  str_monster_ability_2906201 = "Após se tornar Vilanor, suas habilidades são grandemente aprimoradas, ganhando o poder de se mover livremente pelo campo e gerar espadas a partir de energia maligna.",
  str_monster_passiveskill_name_290620101 = "Rancor Profundo",
  str_monster_passiveskill_desc_290620101 = "Antes de se mover, Vilanor convoca fios de Energia da Espada Vil em locais aleatórios com base na quantidade de dano que sofreu nesta rodada. Quanto mais dano sofrido nesta rodada, mais fios de Energia da Espada Vil são convocados.",
  str_monster_name_2004301 = "Energia da Espada Vil",
  str_monster_desc_2004301 = "Esta energia de espada liberada por Vilanor assume uma forma de espada após atingir uma certa densidade.",
  str_monster_ability_2004301 = "A energia da espada invocada por Vilanor não pode atacar ou se mover, mas ocupará a peça em que está, tornando-a intransitável.",
  str_monster_desc_1602191 = "Contender - Istvan",
  str_monster_ability_1602191 = "Após se mover, lança um Ataque Normal ou Combo, causando muito dano aos Eclipsitas.",
  str_monster_ability_1602192 = "Após se mover, lança um Ataque Normal ou Combo em Cadeia, causando muito dano aos Aurorianos.",
  str_monster_name_1600391 = "Istvan",
  str_monster_name_1600391_en = "ISTVAN",
  str_monster_name_70011191 = "Abandonado: Fujikumo Nobutora - Devorar",
  str_monster_name_70011191_en = "Abandonado: Fujikumo Nobutora - Devorar",
  str_monster_ability_70011191 = "Conjure um grande número de fantasmas e libere diferentes habilidades poderosas com base na distância entre os Aurorianos e o inimigo em cada rodada.",
  str_monster_passiveskill_name_200440101 = "Contaminação Mecânica",
  str_monster_passiveskill_desc_200440101 = "Reflete o dano após receber dano dos Ataques Normais dos Aurorians.",
  str_monster_passiveskill_name_200460101 = "Reparo Mecânico",
  str_monster_passiveskill_desc_200460101 = "Recupera uma certa porcentagem do HP perdido no início de cada rodada.",
  str_monster_name_2004401 = "Soldado Voidcross",
  str_monster_desc_2004401 = "Uma arma de guerra criada através da fusão de Eclipsitas e Aurorians. As características dos Aurorians foram mantidas tanto quanto possível, e a mecanização não é muito óbvia, mas ainda é muito perigosa.",
  str_monster_ability_2004401 = "Uma forma de vida mecânica que ataca hackeando e cortando.",
  str_monster_name_2004501 = "Soldado Ululat",
  str_monster_desc_2004501 = "Uma arma de guerra criada através da fusão de Eclipsitas e Aurorians. É protegida por uma espessa camada de armadura mecânica, e sua força foi aprimorada ao máximo possível.",
  str_monster_ability_2004501 = "O poder e a defesa desta forma de vida mecânica modificada foram muito melhorados, e ela é excelente em atacar com explosões e outros métodos semelhantes.",
  str_monster_name_2004601 = "Super-Soldado Meaugm",
  str_monster_name_2004601_en = "Super-Soldado Meaugm",
  str_monster_desc_2004601 = "Uma super arma criada através da fusão de Eclipsitas e Aurorians. Ela não possui mais características Aurorianas e agora é uma existência totalmente mecânica.",
  str_monster_ability_2004601 = "Esta forma de vida mecânica modificada pode usar sua armadura espessa como uma arma, tornando-a muito difícil de lidar.",
  str_monster_name_2906401 = "Super-Soldado Blaugm",
  str_monster_name_2906401_en = "Super-Soldado Blaugm",
  str_monster_desc_2906401 = "Este super soldado é um Eclipsita que foi equipado com dispositivos mecânicos por todo o corpo para torná-lo mais resistente, mais feroz e mais intimidador.",
  str_monster_ability_2906401 = "Um super soldado intimidador que se destaca em esmagar inimigos próximos com seus ataques.",
  str_monster_passiveskill_name_290640101 = "Absorção Mecânica",
  str_monster_passiveskill_desc_290640101 = "Ganha 1 pilha de Armadura Mecânica ao receber um Ataque Normal. Cada pilha reduz em 1% o Ataque Normal recebido. O número de pilhas deste buff é reduzido pela metade no início da rodada.",
  str_monster_passiveskill_name_290640102 = "Defesa Mecânica",
  str_monster_passiveskill_desc_290640102 = "Reduz o dano recebido de ataques frontais.",
  str_monster_passiveskill_name_290640103 = "Frenesi Mecânico",
  str_monster_passiveskill_desc_290640103 = "Aumenta o dano à medida que o próprio HP diminui.",
  str_monster_name_2906301 = "Ulysses Bio",
  str_monster_name_2906301_en = "Ulysses Bio",
  str_monster_desc_2906301 = "Ulysses modificou seu corpo extensivamente para realizar seus ideais extremos. Ele não é mais um Aurorian agora.",
  str_monster_ability_2906301 = "Ulysses usa diferentes estratégias de ataque com base nas habilidades dos Aurorianos.",
  str_monster_passiveskill_desc_8024441 = "Quando um Murkmite atinge um alvo, reduz os pontos de força do alvo em 2.",
  str_monster_name_8024161 = "Vontade Malévola: Sombra",
  str_monster_name_8024442 = "Vontade Malévola: Murkmite",
  str_monster_name_80243111 = "Vontade Malévola: Augean",
  str_monster_name_80243111_en = "Vontade Malévola: Augean",
  str_monster_name_7001121 = "Esquecidos: Rei Tritão",
  str_monster_ability_7001121 = "Ataques causam recuo. Pode invocar Armas de Salva em locais específicos no campo de batalha.",
  str_monster_name_7001121_en = "Esquecidos: Rei Tritão",
  str_monster_passiveskill_name_7001121 = "Implantação de Arma Salvo",
  str_monster_passiveskill_desc_7001121 = "No início da rodada do jogador, se houver menos de 3 Salvo Guns no campo de batalha, invoca 4 Salvo Guns.",
  str_monster_name_2004701 = "Demônio: Rato",
  str_monster_desc_2004701 = "Fiendlings onívoros de pequeno porte com cultivo insuficiente, mantendo uma natureza selvagem. Eles sempre se infiltram em moradias aurorianas para roubar comida. Alguns mais agressivos podem até causar danos.",
  str_monster_ability_2004701 = "Ágil e rápido, ele se move rapidamente para trás do alvo após um ataque.",
  str_monster_passiveskill_name_2004701 = "Roer do Roedor",
  str_monster_passiveskill_desc_2004701 = "Mira no Auroriano com a menor DEF na equipe ao atacar, causando dano.",
  str_monster_ability_5412041 = "Um Eclipsite com habilidades de invocação. Incapaz de se mover por conta própria, ele luta invocando Gloom Ghouls que possuem habilidades de ataque à distância. Gloom Ghouls sacrificam sua própria HP para curar Croweye ao entrar na batalha e transferem danos para Croweye quando recebem danos.",
  str_monster_passiveskill_name_5412042 = "Simbiose do Sacrifício",
  str_monster_passiveskill_desc_5412042 = "Ele sacrifica seu próprio PV para curar Croweye ao entrar na batalha e transfere dano para Croweye quando recebe dano.",
  str_monster_name_541100216 = "Chen'ni",
  str_monster_desc_541100216 = "A criança que apareceu de repente do nada parecia ser um demônio peculiar com uma aparência como a nossa?",
  str_monster_ability_541100216 = "As habilidades dela são impressionantes!",
  str_monster_passiveskill_desc_541301215 = "No início da rodada do jogador, se houver menos de 2 Salvo Guns no campo de batalha, convoca 4 Salvo Guns.",
  str_monster_name_2909301 = "Demônio: Nian",
  str_monster_name_2909301_en = "Demônio: Nian",
  str_monster_desc_2909301 = "A lenda diz que na véspera do Festival da Primavera, um demônio feroz e bestial desce sobre Longzhou, causando caos. Aqueles que conseguem expulsá-lo são abençoados com um ano inteiro de paz e boa sorte.",
  str_monster_ability_2909301 = "Nian destruirá tudo à vista conforme se aproxima da aldeia. Apenas Aurorianos que possuem Habilidades Ativas poderosas são capazes de detê-lo.",
  str_monster_passiveskill_name_2909301 = "Besta Antiga Formidável",
  str_monster_passiveskill_desc_2909301 = "A presença formidável de Nian é aterrorizante! Ladrilhos dentro de 1 aglomerado ao redor não podem ser selecionados como pontos de desembarque dos Aurorianos.",
  str_monster_passiveskill_name_2909302 = "Estoure o Portão",
  str_monster_passiveskill_desc_2909302 = "A fera Nian destruirá o portão e, ao entrar, devastará tudo, fazendo a batalha fracassar.",
  str_monster_name_70011251 = "Desamparado: Cerritus",
  str_monster_name_70011251_en = "Desamparado: Cerritus",
  str_monster_desc_70011251 = "O novo Eclipsite encontrado durante a exploração parece ser uma variante de um poderoso Eclipsite, exceto que é mais perturbado e muito mais destrutivo.",
  str_monster_ability_70011251 = "Abandonado: Cerritus ataca os aurorianos, invocando seixos e gerando continuamente ladrilhos enfraquecidos no campo. Ele também pode aumentar seu próprio ACT durante o combate.",
  str_monster_name_70011261 = "Esquecido: Chandra",
  str_monster_name_70011261_en = "Abandonado: Chandra",
  str_monster_desc_70011261 = "Uma pesquisadora de Illumina otimista e alegre, ela possui uma habilidade especial para absorver emoções negativas dos outros e curar traumas mentais.",
  str_monster_ability_70011261 = "Abandonado: Chandra pode lançar ataques em Aurorians à distância e aumentar continuamente o número de vezes que sua habilidade causa dano.",
  str_monster_passiveskill_name_70011261 = "Abandonado: Colher Emoções Negativas",
  str_monster_passiveskill_desc_70011261 = "A cada conjuração de Renegado: Projeto de Emoção Negativa, a habilidade lança 1 ataque a mais na próxima vez, causando um aumento no dano total.",
  str_monster_passiveskill_name_80051412 = "Estratégia de Frente de Guerra",
  str_monster_passiveskill_desc_80051412 = "O Courier pode armazenar energia de batalha para motivar monstros. Quando há mais de 30 pontos de energia de batalha, ele fornece um aumento permanente de 10% no ATK para todos os monstros no campo ao final de cada rodada. No entanto, o Courier irá desencadear uma explosão de energia ao morrer, causando um dano massivo a todos os monstros no campo.",
  str_monster_passiveskill_name_80051413 = "Acesso à Energia",
  str_monster_passiveskill_desc_80051413 = "O Courier restaura automaticamente 10 pilhas de energia de batalha no início de cada rodada. Quando o Auroriano lança uma Habilidade Ativa no campo, reduz as pilhas de energia de batalha do Courier em 4. Além disso, o Courier perde 1 pilha de energia de batalha quando atingido pelo ataque normal do Auroriano.",
  str_monster_name_2909401 = "Ira",
  str_monster_name_2909401_en = "Ira",
  str_monster_desc_2909401 = "Um Wraith enigmático e formidável, percorrendo as terras para treinamento. Seu hálito exala terror, prenunciando a ruína para aqueles que despertam sua ira.",
  str_monster_ability_2909401 = [[
Capaz de invocar Fogo Sombrio com Darkflow na batalha.
Nota: O Meteorito Darkflow de Ira, composto por chamas furiosas, pode matar instantaneamente Aurorianos dentro de seu alcance.]],
  str_monster_name_2004801 = "Sombrafogo",
  str_monster_passiveskill_name_2004801 = "Cinzas do Fogo Sombrio",
  str_monster_passiveskill_desc_2004801 = "Após a eliminação, Shadowfire deixa Ladrilhos Escuros em sua localização.",
  str_monster_ability_5435071 = "Os ataques causam recuo. Pode invocar armas de salva em ladrilhos próximos para autoproteção.",
  str_monster_ability_5435112 = "Abrigue-se em um local seguro, sacrificando uma parte do HP a cada rodada para restaurar o HP de Philex.",
  str_monster_name_70011271 = "Abandonado: Caracalune",
  str_monster_name_70011271_en = "Abandonado: Caracalune",
  str_monster_name_70011281 = "Forsaken: Maude Solus",
  str_monster_name_70011281_en = "Forsaken: Maude Solus",
  str_monster_ability_70011271 = "Excelente no uso de ataques de grande área. Trava os elementos dos ladrilhos ao seu redor depois que ele se move.",
  str_monster_name_70011321 = "Esquecidos: Aranha Queen",
  str_monster_name_70011321_en = "Forsaken: Arachnid Queen",
  str_monster_ability_70011321 = "Possuindo fortes habilidades reprodutivas, tece teias de aranha em um ambiente de caça e convoca um grande número de descendentes de aranha para se juntar à batalha a cada 3 rodadas.",
  str_monster_name_70110011 = "Abandonado: Luto Eve",
  str_monster_name_70110011_en = "Abandonado:Luto Eve",
  str_monster_desc_70110011 = "A dor do isolamento e o medo de ser cortado, aquelas memórias insuportáveis do passado, moldaram a pessoa conhecida como Eve hoje.",
  str_monster_ability_70110011 = "A cada rodada, invoque Dawn Flores em um local definido no campo de batalha, aumentando a DEF de acordo com o número de Dawn Flores.",
  str_monster_passiveskill_name_70110011 = "Luto: Metamorfose",
  str_monster_passiveskill_desc_70110011 = "A cada rodada, invoque Dawn Flores em um local definido para aumentar a DEF; cada Flor Dawn concede um aumento extra de DEF.",
  str_monster_name_70110012 = "Dawn Flor",
  str_monster_desc_70110012 = "Essas simples flores brancas, pequenas e comuns, estão entre os confortos mais preciosos em seu coração.",
  str_monster_ability_70110012 = "Concede um bônus adicional de DEF para Grieving Eve.",
  str_monster_name_7001134 = "Abandonado: Bennuguardian",
  str_monster_name_7001134_en = "Abandonado:Bennuguardian",
  str_monster_ability_7001134 = "Possui grande poder. Acumula Fúria quando atacado. Quando a Fúria atinge um certo nível, entra em um estado Enfurecido, reduzindo o dano recebido e lançando habilidades poderosas adicionais.",
  str_monster_name_2004901 = "Neblina",
  str_monster_desc_2004901 = "Formado pela rápida acumulação de Fluxo Escuro ao redor dos Eclipsitas mortos. Cuidado! A raiva e o ressentimento dos Eclipsitas continuam vivos dentro dele.",
  str_monster_ability_2004901 = "Todo o dano que recebe é reduzido para 1. Ele não pode atacar, mas continuará se movendo em direção aos aurorianos.",
  str_monster_passiveskill_name_2004901 = "Névoa Enredante",
  str_monster_passiveskill_desc_2004901 = "Todo o dano que recebe é reduzido para 1. Ele não pode atacar, mas continuará se movendo em direção aos Aurorianos e desaparecerá se for submetido a efeitos de deslocamento. Desaparece normalmente após 2 rodadas.",
  str_monster_passiveskill_desc_2004902 = "Todo o dano que recebe é reduzido para 1. Ele não pode atacar, mas continuará se movendo em direção aos Aurorianos e desaparecerá se for submetido a efeitos de deslocamento. Desaparece normalmente após 3 rodadas.",
  str_monster_name_2909501 = "Cenoura: Praga",
  str_monster_name_2909501_en = "Cenoura: Praga",
  str_monster_desc_2909501 = "Após absorver muito ressentimento em um lugar escuro e apodrecer, esta cenoura se transformou em uma criatura bizarra que busca vingança após ganhar o poder do Fluxo Escuro.",
  str_monster_ability_2909501 = "Lança cenouras, causando múltiplos danos. Quando gira em alta velocidade, causa múltiplos danos aos inimigos em uma grande área e os repele.",
  str_monster_ability_2909502 = "Lança cenouras, causando múltiplos danos. Quando gira em alta velocidade, causa múltiplos danos aos inimigos em uma grande área e os repele.\nEm emergências, pode encolher e se enterrar no chão e continuar lutando a partir daí.",
  str_monster_passiveskill_name_2909502 = "Praga: Toca",
  str_monster_passiveskill_desc_2909502 = "Se for invencível quando entrar em ação, ele se torna menor, se enterra no solo e recupera seu HP total.",
  str_monster_ability_5455121 = "Pode usar ataques em forma de cruz ou de tela inteira, e invocar raios.",
  str_monster_ability_4910302 = "Possui alto ATK e pode causar grande dano em forma radial até o alcance máximo.",
  str_monster_ability_5455091 = "Kittypus agita seus tentáculos para causar um dano massivo aos Aurorianos.",
  str_monster_name_2909701 = "Magmite Insaciável",
  str_monster_name_2909701_en = "Magmite Insaciável",
  str_monster_desc_2909701 = "Um tipo aberrante de Eclipsita que usa tanto lava quanto Fluxo Escuro para causar dano.",
  str_monster_ability_2909701 = "Pode causar dano em uma grande área, além de invocar um escudo de magma para se proteger.",
  str_monster_passiveskill_name_2909701 = "Lava Refletora",
  str_monster_passiveskill_desc_2909701 = "Enquanto protegido por seu escudo de magma, reflete todos os ataques normais recebidos dos Aurorians.",
  str_monster_name_80063701 = "Bandido da Cidade",
  str_monster_desc_80063701 = "Capangas que dominaram o uso da besta e sabem como atacar com precisão, furtivamente e, o mais importante... com segurança.",
  str_monster_ability_80063701 = "Pode atacar alvos em forma de cruz até a extensão máxima de seu alcance.",
  str_monster_name_80063801 = "Elite da Cidade Bandido",
  str_monster_desc_80063801 = "Diz-se que são guerreiros de elite habilidosos com armas de fogo e possuem uma agilidade incrível.",
  str_monster_ability_80063801 = "Causa dano duas vezes após usar sua incrível agilidade para se distanciar do alvo.",
  str_monster_ability_2910242 = "Destaca-se no uso de ataques de grande área; ataques de longuíssima distância causam mais dano a alvos distantes.",
  str_monster_ability_2920232 = "Vani pode usar energia para atacar à distância.",
  str_monster_passiveskill_name_20007011 = "Promoção",
  str_monster_passiveskill_desc_20007011 = "Ao chegar na borda do Tabuleiro de Alquimia, eles são promovidos a Torre Furiosa, Cavalo Caído, Bispo Eclipse ou Queen Ardilosa, de acordo com sua ordem de chegada.",
  str_monster_passiveskill_name_20007111 = "Promoção Elite",
  str_monster_passiveskill_desc_20007111 = "Ao chegar na borda do Tabuleiro de Alquimia, eles são promovidos a Torre Furiosa - RAM, Cavalo Caído - CHARGE, Bispo Eclipse - EX ou Queen Ardilosa, de acordo com sua ordem de chegada.",
  str_monster_passiveskill_name_2910242 = "Nunca Desista",
  str_monster_passiveskill_desc_2910242 = "Chifre Feroz se torna mais forte toda vez que a barra de HP atual é reduzida a zero.",
  str_monster_passiveskill_name_2010171 = "Carregando",
  str_monster_passiveskill_desc_2010171 = "Reduz em 1 o tempo de recarga da habilidade do Capitão Auroriano sempre que ele é eliminado.",
  str_monster_passiveskill_name_2914001 = "Destemida",
  str_monster_passiveskill_desc_2914001 = "Recebe apenas 1 dano de ataques.",
  str_monster_passiveskill_name_29140011 = "Escolta",
  str_monster_passiveskill_desc_29140011 = "Vani recupera PV igual a 200% do dano que Bennuguardian causa.",
  str_monster_passiveskill_name_2920232 = "Tenacidade",
  str_monster_passiveskill_desc_2920232 = "Aumenta a DEF à medida que o HP diminui.",
  str_monster_passiveskill_name_2010715 = "Enfraquecimento",
  str_monster_passiveskill_desc_2010715 = "Reduz a DEF do Queen Ardiloso sempre que um Eclipsite morre.",
  str_monster_passiveskill_name_20107152 = "Proteção",
  str_monster_passiveskill_desc_20107152 = "Se a Queen Ardilosa tem Salvaguarda ao tomar uma ação, concede 3 pilhas de Salvaguarda a todas as outras Eclipsitas.",
  str_monster_passiveskill_name_2910801 = "Nunca Desista",
  str_monster_passiveskill_desc_2910801 = "O Monarca Desolado se torna mais forte toda vez que sua barra de HP é reduzida a zero. Alguns Eclipsitas Adormecidos também serão despertados.",
  str_monster_passiveskill_name_29006411 = "Tranca",
  str_monster_passiveskill_desc_29006411 = "Anula as habilidades ativas de Aurorian, causando dano aos Aurorianos e convocando Ladrilhos Trancados nos 4 ladrilhos ao redor deles.",
  str_monster_passiveskill_name_29006611 = "Esmagar",
  str_monster_passiveskill_desc_29006611 = "Anula as habilidades ativas aurorianas, convocando aleatoriamente ladrilhos danificados.",
  str_monster_name_1502001 = "Abandonado: Anatoli",
  str_monster_name_1502001_en = "Anatoli",
  str_monster_desc_1502001 = "Um oficial de inteligência calmo e confiável da Federação Illumina que ocasionalmente faz reclamações inesperadas. Ninguém sabe se essas reclamações são feitas intencionalmente ou não.",
  str_monster_ability_1502001 = "Puxa as unidades inimigas para controlar a situação da batalha mais facilmente.",
  str_monster_name_1501761 = "Abandonado: Beretta",
  str_monster_name_1501761_en = "Beretta",
  str_monster_desc_1501761 = "Um médico de combate de Lumopolis já foi salvo por um médico chamado John. Desde então, ela decidiu se tornar uma boa médica.",
  str_monster_ability_1501761 = "Usa habilmente a Lança Australis para causar dano aos inimigos. Tem a capacidade de contra-atacar as Habilidades Ativas Aurorianas.",
  str_monster_passiveskill_name_1501761 = "Balcão Australis",
  str_monster_passiveskill_desc_1501761 = "Anula as habilidades ativas de Aurorian, concedendo 1 marca de Lança Australis. Causa dano 1 vez adicional ao lançar Tempestade Australis.",
  str_monster_name_70011291 = "Abandonado: Dragão Malvado Hakudoma",
