  str_monster_desc_700201901 = "Sua natureza intrépida e desinibida, assim como sua impulsividade, são as marcas de uma verdadeira alma roqueira! Seu feroz estilo musical a tornou muito popular na Rediesel Wrench, permitindo a ela não apenas inspirar as tropas, mas também liderá-las na batalha.",
