  str_monster_name_2005301 = "Pistola Salva",
  str_monster_desc_2005301 = "Está aprendendo sobre os Aurorianos, mas tem dificuldade em entender quando disparar o tiro de saudação. Tudo o que quer é sussurrar ternamente, mas acaba se tornando um veneno do mar profundo que corrói todos que se aproximam.",
